function filteredOrders(){const rows=pipelineOrders().filter(o=>(!ui.orderSupplier||o.vendorId===ui.orderSupplier)&&(!ui.status||orderStatus(o)===ui.status)&&(!ui.search||[softwareReference(state,'orders',o.id),String(o.serialNumber),o.number,o.pi?.number,vendor(o)?.name,vendor(o)?.code,...o.lines.map(l=>l.code)].join(' ').toLowerCase().includes(ui.search.toLowerCase())));if(ui.orderSort==='default')return rows;const [field,direction]=ui.orderSort.split('-'),factor=direction==='desc'?-1:1;const value=o=>field==='serial'?o.serialNumber:field==='supplier'?vendor(o)?.name:o.number;return rows.sort((a,b)=>{const av=value(a),bv=value(b),am=av==null||av==='',bm=bv==null||bv==='';if(am!==bm)return am?1:-1;const result=field==='serial'?Number(av)-Number(bv):orderCollator.compare(String(av||''),String(bv||''));return factor*result||(a.serialNumber||0)-(b.serialNumber||0)||orderCollator.compare(a.id,b.id);});}
