async function api(path,options={}){const r=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{}),...options.headers}});const data=await r.json();if(!r.ok){const error=new Error(data.error||'Request failed');error.status=r.status;throw error;}return data;}
function writeView(){return ui.modal&&ui.editView?ui.editView:{expectedRevision:state.revision,editContext};}
const saveRecovery=createSaveRecovery({context:()=>({state,user}),fetchLatest:()=>api('/bootstrap'),esc,adopt:r=>{state=r.state;editContext=r.editContext||null;user=r.user;csrf=r.csrf;ui.editView={expectedRevision:state.revision,editContext};}});
const sessionRecovery=createSessionRecovery({context:()=>({user}),esc,reauthenticate:async(email,password)=>{await api('/login',{method:'POST',body:JSON.stringify({email,password})});return api('/bootstrap');},applySession:fresh=>{csrf=fresh.csrf;user=fresh.user;}});
function showRequestError(e){if(sessionRecovery.show(e)){showError('Your sign-in expired. Your entries and selected files are still here.');return;}showError(e.message);saveRecovery.show(e);}
async function refreshIdleView(){if(sandbox||!user||!state||ui.modal||busy||submitting||pageDirty||document.hidden||document.querySelector('#save-conflict'))return;const actor=user.id,revision=state.revision;try{const r=await api('/revision');if(r.revision===revision)return;const fresh=await api('/bootstrap');if(ui.modal||busy||submitting||pageDirty||user.id!==actor||state.revision!==revision||fresh.user.id!==actor)return;state=fresh.state;editContext=fresh.editContext||null;user=fresh.user;csrf=fresh.csrf;const scroll=window.scrollY;render();window.scrollTo(0,scroll);}catch(e){sessionRecovery.show(e);/* Background refresh must not disturb open work or submit anything. */}}
function persist(s){try{localStorage.setItem(STORE,JSON.stringify(s));}catch{throw new Error('Browser storage is full or unavailable. Export a backup; the change was not saved.');}}
function toast(s,error=false){clearTimeout(timer);$('#toast-root').innerHTML=`<div class="toast ${error?'error':''}" role="status">${icon(error?'alert':'check',16)}<span>${esc(s)}</span></div>`;timer=setTimeout(()=>$('#toast-root').innerHTML='',6500);}
async function command(type,payload,{close=true,message='Saved with visible history.'}={}){
 if(busy)return;busy=true;const submit=$('#dialog-form [type=submit]');if(submit)submit.disabled=true;let attemptKey=null;
 try{let result;if(sandbox){const r=execute(state,{type,payload},user);persist(r.state);state=r.state;editContext=r.editContext||null;user=state.users.find(u=>u.id===user.id);result=r.result;}else{
  attemptKey='fh-pending-command:'+user.id;const signature=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify({type,payload}))))).map(v=>v.toString(16).padStart(2,'0')).join('');let prior=null;try{prior=JSON.parse(sessionStorage.getItem(attemptKey)||'null');}catch{throw new Error('Unable to read the pending-save record. Keep this form open and ask your administrator for help.');}
  if(prior&&prior.signature!==signature){const receipt=await api('/requests/'+encodeURIComponent(prior.id));sessionStorage.removeItem(attemptKey);if(receipt.committed){const fresh=await api('/bootstrap');state=fresh.state;editContext=fresh.editContext||null;csrf=fresh.csrf;user=fresh.user;render();throw new Error('Your earlier save succeeded. Review the updated order before saving these changed entries.');}throw new Error('The earlier save was not found. Your entries remain here. Review them and press Save again.');}
  const requestId=prior?.id||crypto.randomUUID();sessionStorage.setItem(attemptKey,JSON.stringify({id:requestId,signature}));const r=await api('/commands',{method:'POST',headers:{'Idempotency-Key':requestId},body:JSON.stringify({type,payload,...writeView()})});sessionStorage.removeItem(attemptKey);state=r.state;editContext=r.editContext||null;user=state.users.find(u=>u.id===user.id);result=r.result;
 }pageDirty=false;if(close)closeModal();else if(ui.modal)ui.editView={expectedRevision:state.revision,editContext};render();toast(message);return result;
 }catch(e){if(attemptKey&&[400,401,403,409,413,429].includes(e.status))sessionStorage.removeItem(attemptKey);showRequestError(Object.assign(e,{message:e.status||sandbox?e.message:e.message+' If the connection failed, keep this form open and retry the same details.'}));return null;}finally{busy=false;if(submit)submit.disabled=false;}
}
function showError(s){const e=$('#modal-error');if(e){e.textContent=s;e.classList.add('visible');e.scrollIntoView({block:'nearest'});}else toast(s,true);}
function navigate(view){closeModal();ui.mobile=false;location.hash='#/'+view;route();}
function route(){ui.mobile=false;const p=(location.hash||'#/home').replace(/^#\/?/,'').split('/');ui.view=p[0]||'home';ui.vmsPage=ui.view==='vms'&&p[1]==='module'?p[2]||'dashboard':null;ui.orderId=ui.vmsPage?null:p[1]||null;ui.search='';ui.status='';ui.page=1;ui.selectedOrders=[];ui.orderList='active';ui.orderSupplier='';ui.orderSort='default';render();if((ui.view==='settings'||ui.view==='vms'&&ui.vmsPage==='users')&&!sandbox&&user.role==='ADMIN')loadUserAccounts();}
async function start(){if(sandbox){try{state=JSON.parse(localStorage.getItem(STORE));if(state?.schemaVersion!==SCHEMA_VERSION)state=null;}catch{}state=state||window.FH_INITIAL_STATE||createCleanSeed();const serialsChanged=ensureOrderSerials(state),referencesChanged=ensureRecordReferences(state);if(serialsChanged||referencesChanged){state.revision++;persist(state);}let saved;try{saved=localStorage.getItem(STORE+'-user');}catch{}user=state.users.find(u=>u.id===saved)||state.users[1]||state.users[0];}else{try{const r=await api('/bootstrap');state=r.state;editContext=r.editContext||null;user=r.user;csrf=r.csrf;}catch(e){if(e.status===401)return loginView();$('#app').innerHTML='<div class="boot" role="alert"><h1>Unable to load workspace</h1><p>Check your connection and try again. Your saved records have not been changed.</p><button type="button" class="button primary" id="retry-start">Try again</button></div>';$('#retry-start').addEventListener('click',()=>start());return;}}route();vmsModule.start();}
function demoStrip(){return `<div class="demo-strip">${icon('info',14)}<span>${sandbox?'Clean test workspace: final Vendor Master + 129 Base Item Codes + generated GJ/KD/TT ERP Item Codes + filtered base-product price lists + historical freight benchmarks are loaded. No demo POs, payments, shipments or complaints are preloaded.':'Local pilot only. PLM is active in this build; live VMS synchronization and ERP connections are not enabled.'}</span><a href="#/versions">Build details ${icon('arrow',12)}</a></div>`;}
function sidebar(){return navigation.sidebar();}
function topbar(){const titles={home:'Modules','order-management':'Order Management',overview:'Overview',orders:'Order pipeline',order:getOrder(ui.orderId)?.number||'Order',tasks:'Tasks & follow-ups',payments:'Payments',shipments:'Shipping & freight',documents:'QC & documents',vms:'Vendor Management System',vendors:'Vendor master',prices:'Supplier price lists',plm:'Product Lifecycle',product:'PLM product',items:'Item master',settings:'Users & settings',references:'Software references',versions:'Version & edit log'};return `<header class="topbar"><div class="flex"><button class="icon-button mobile-toggle" data-action="mobile" aria-label="Open navigation">${icon('menu')}</button>${navigation.breadcrumb(titles[ui.view]||'Roadmap')}</div><div class="top-tools">${navigation.area()==='orders'&&ui.view!=='order-management'?'<div class="search-top">': '<div class="search-top module-search-hidden">'}${icon('search',13)}<input id="global-search" placeholder="Find a PO or brand SKU…" aria-label="Find a PO or brand SKU"><small>↵</small></div><button class="icon-button ${navigation.area()==='orders'&&ui.view!=='order-management'?'':'module-search-hidden'}" data-action="nav" data-to="tasks" aria-label="View due tasks">${icon('bell')}</button><div class="account"><span class="avatar">${esc(user.name.split(' ').slice(0,2).map(x=>x[0]).join(''))}</span><div>${sandbox?`<select id="demo-role" aria-label="Review role">${state.users.map(u=>`<option value="${u.id}" ${u.id===user.id?'selected':''}>${esc(u.name.replace('Demo ',''))}</option>`).join('')}</select>`:`<span class="small strong">${esc(user.name)}</span>`}<small>${sandbox?'Review role · not authentication':esc(user.role)}</small></div>${sandbox?'':button('Sign out','logout',{},'small ghost')}</div></div></header>`;}
