function render(){if(!state||!user)return;syncPersonalAppearance(user);const views={domestic:()=>domesticUI.page(),references:()=>referencePages.render(),home:()=>navigation.home(),'order-management':()=>navigation.orderHub(),overview:overviewView,orders:ordersView,order:orderView,tasks:tasksView,payments:paymentsView,shipments:shipmentsView,documents:documentsView,vms:()=>vmsModule.render(),vendors:vendorsView,prices:priceListsView,plm:plmView,product:productView,items:itemsView,settings:settingsView,versions:versionsView,roadmap:roadmapView};$('#app').innerHTML=sidebar()+(ui.mobile?'<button type="button" class="nav-scrim" data-action="mobile" aria-label="Close navigation"></button>':'')+`<div class="workspace module-shell" data-view="${esc(ui.view)}">${topbar()}<main class="content">${(views[ui.view]||overviewView)()}<div class="footer-note"><span>Farming Hub Purchase Management · ${sandbox?'isolated browser review':'local authenticated pilot'}</span><span>v${APP_VERSION} · ${state.demo?'Sample approvals and payments are illustrative':'Manual tracking, no bank / inventory posting'}</span></div></main></div>`;}
function flagList(flags,max=6){return flags.slice(0,max).map(f=>`<div class="flag-row"><div class="flag-icon ${f.level==='warning'?'warning':''}">${icon('alert',14)}</div><div class="flag-body"><div class="flag-title">${esc(f.label)}</div><div class="flag-meta">${esc(f.detail)}</div><a href="#/order/${f.orderId}">${esc(getOrder(f.orderId)?.number)} · ${esc(f.owner)}</a></div><button class="icon-button" data-action="open-order" data-id="${f.orderId}" aria-label="Open flagged order">${icon('chevron',12)}</button></div>`).join('')||empty('No current flags','Dates and open work are within configured thresholds.','check');}
const laterPipelineGroups=[['In production',['IN_PRODUCTION']],['Shipment readiness',['READY_TO_SHIP']],['Transit',['IN_TRANSIT','PARTIAL_ARRIVAL']],['Port arrived / closed',['PORT_ARRIVED','SHORT_CLOSED']]];
