const fxCurrencyLabel=c=>c==='CNY'?'RMB':c;
const bankRateLabel=c=>fxCurrencyLabel(c)+' to INR (Indian bank)';
const currencyPairLabel=(from,to)=>fxCurrencyLabel(from)+' to '+fxCurrencyLabel(to);
const bocRateFor=(p,a)=>a&&Object.hasOwn(a,'bocUsdRmbRate')?a.bocUsdRmbRate:p.bocUsdRmbRate;
const bocRateText=rate=>rate==null?'':String(rate/1e6);
function bocRateField(currency,value='',attrs=''){const markup=field('bocUsdRmbRate','USD to RMB (BOC, optional)',value,'number',{attrs:'min="0.000001" step="0.000001" '+attrs+(currency==='USD'?'':' disabled'),hint:'RMB for 1 USD. Reference only; actual receipt is entered separately.'});return currency==='USD'?markup:markup.replace('<div ','<div hidden ');}
function updateInitialRateLabels(currency){const bank=$('[name=inrRate]'),supplier=$('[name=invoiceRate]'),boc=$('[name=bocUsdRmbRate]');if(bank)bank.closest('label').firstChild.textContent=bankRateLabel(currency);if(supplier)supplier.closest('label').firstChild.textContent=currencyPairLabel(currency,getOrder(ui.data.id).currency)+' (supplier)';if(boc){boc.disabled=currency!=='USD';boc.closest('.field').hidden=currency!=='USD';if(boc.disabled)boc.value='';}}
function orderFinance(o){const f=financials(state,o),ed=canEdit(user,o),alloc=state.payments.flatMap(p=>p.allocations.filter(a=>a.orderId===o.id).map(a=>({p,a})));return `<div class="grid-two"><div class="panel">${ph('Supplier proforma invoice',esc(o.pi?.number||'Not received'),ed?button(o.pi?'Replace PI':'Upload PI','pi',{id:o.id},'small','upload'):'')}<div class="panel-body">${o.pi?`<div class="kv-grid">${kv('PI amount',formatMoney(o.pi.amountMinor,o.pi.currency))}${kv('Status',badge(o.pi.status,o.pi.status==='APPROVED'?'green':'amber'))}${kv('PI date',dt(o.pi.date))}${kv('Quantity',o.pi.quantity+' units')}</div><div class="gap"></div><div class="flex wrap">${evidenceButtons(o.pi,'Open PI')}${ed&&['RECEIVED','REVERIFY'].includes(o.pi.status)?button('Verify PI','verify-pi',{id:o.id},'small primary','check'):''}${canPerformApproval(user,'APPROVE_PI',o.scope,null,state,o)&&o.pi.status==='VERIFIED'?button('Approve PI','approve-pi',{id:o.id},'small primary','check'):''}</div>`:empty('PI required before payment','Purchase verification precedes manager approval.','file')}</div></div><div class="panel">${ph('Original-order settlement','Reported payment is not supplier-confirmed realization.')}<div class="panel-body"><div class="kv-grid">${kv('Order obligation',formatMoney(f.total,o.currency))}${kv('Reported equivalent',formatMoney(f.reported,o.currency))}${kv('Actual supplier realization',formatMoney(f.realized,o.currency))}${kv('Original-order balance',formatMoney(f.balance,o.currency))}</div><div class="gap"></div>${note(`${f.pending} allocation(s) awaiting receipt. Differences remain on this order; no automatic cross-order adjustment.`)}</div></div></div><div class="gap"></div><div class="panel">${ph('Terms-driven payment milestones',esc(o.paymentTerms.name),ed?button('Record bank payment','payment',{id:o.id},'small primary','plus'):'')}<div class="table-wrap"><table><thead><tr><th>Milestone</th><th>Shipment / trigger</th><th>Due date</th><th class="right">Obligation</th><th class="right">Reported / realized</th><th>Authorization</th></tr></thead><tbody>${paymentSchedule(state,o).map(m=>`<tr><td class="strong">${esc(m.name)}<div class="sub">${m.percent}%</div></td><td>${esc(m.shipmentLabel||'Order / unallocated')}<div class="sub">${m.trigger}</div></td><td>${m.due?dt(m.due):badge('Awaiting '+m.awaiting,'dark')}</td><td class="right">${formatMoney(m.amount,o.currency)}</td><td class="right">${formatMoney(m.reported,o.currency)}<div class="sub">Realized ${formatMoney(m.paid,o.currency)}</div></td><td>${m.authorized?badge('Authorized','green'):canPerformApproval(user,'AUTHORIZE_PAYMENT',o.scope,null,state,o)&&o.pi?.status==='APPROVED'&&(m.trigger==='PI'||m.shipmentId)?button('Authorize','authorize-payment',{id:o.id,term:m.index,shipment:m.shipmentId||''},'small'):badge('Not authorized','amber')}</td></tr>`).join('')}</tbody></table></div></div><div class="gap"></div><div class="panel">${ph('Bank payment allocations','Multiple orders can share one remittance; each amount stays traceable.')}<div class="table-wrap"><table><thead><tr><th>Reference</th><th>Date</th><th>Allocated</th><th>Supplier realization</th><th>USD to RMB (BOC)</th><th>State</th><th></th></tr></thead><tbody>${alloc.map(({p,a})=>`<tr><td class="mono">${esc(p.reference)}${referencePages.caption('payments',p.id)}</td><td>${dt(p.date)}</td><td>${formatMoney(a.remitMinor,p.currency)}</td><td>${a.realizedMinor===null?'Pending':formatMoney(a.realizedMinor,a.invoiceCurrency)}</td><td>${esc(bocRateText(bocRateFor(p,a)))||'&#8212;'}</td><td>${badge(p.status,p.status==='VOID'?'red':a.realizedMinor!==null?'green':'amber')}</td><td>${ed&&p.status!=='VOID'?button(a.realizedMinor===null?'Record receipt':'Correct receipt','receipt',{id:o.id,payment:p.id,allocation:a.id},'small'):''}</td></tr>`).join('')||`<tr><td colspan="7">${empty('No payments reported')}</td></tr>`}</tbody></table></div></div><div class="gap"></div><div class="panel">${ph('Estimated and actual costs','Native-currency costs, not an accounting ledger.',ed?button('Add cost','cost',{id:o.id},'small','plus'):'')}<div class="table-wrap"><table><thead><tr><th>Category</th><th>Kind</th><th>Remarks</th><th class="right">Amount</th></tr></thead><tbody>${state.costs.filter(c=>c.orderId===o.id).map(c=>`<tr><td>${esc(c.category)}</td><td>${badge(c.kind,'dark')}</td><td>${esc(c.remarks)}</td><td class="right">${formatMoney(c.amountMinor,c.currency)}</td></tr>`).join('')||`<tr><td colspan="4">${empty('No additional costs recorded')}</td></tr>`}</tbody></table></div></div>`;}
function shipmentCard(o,s){const ed=canEdit(user,o),open=s.status!=='CANCELLED',rv=rateVariance(state,s),missing=shippingDocReadiness(o,s),milestones=milestoneRows(s);const rate=latestRateFor(state,s);return `<div class="panel" style="margin-bottom:18px">${ph(`<span class="code-link">${esc(s.number)}</span> &nbsp; ${badge(s.bookingStatus||s.status,s.actualArrival?'green':s.actualDeparture?'blue':s.bookingStatus==='RELEASED'?'amber':'dark')}`,`${esc(o.number)} · ${esc(s.container||'Container not released')} · ${s.lines.reduce((n,l)=>n+l.quantity,0)} units`,button('Order','open-order',{id:o.id},'small ghost','arrow'))}<div class="shipment-facts">${kv('Forwarder Ref',esc(s.forwarderRef||'Not booked'))}${kv('Forwarder',esc(state.vendors.find(v=>v.id===s.forwarderId)?.name||'Not assigned'))}${kv('Booked freight',s.bookedFreightUsdMinor?formatMoney(s.bookedFreightUsdMinor,'USD'):'Not booked')}${kv('Latest weekly rate',rate?'USD '+Number(rate.rateUsd).toLocaleString('en-IN')+' · '+esc(rate.weekCode):'No matched rate')}${kv('Route',esc([s.origin,s.via?`via ${s.via}`:'',s.destination].filter(Boolean).join(' → ')))}${kv('Vessel / voyage',esc([s.vessel,s.voyage].filter(Boolean).join(' · ')||'Required before vessel loading'))}${kv('Baseline → current ETD',sd(s.baselineEtd)+' → <b class="'+(s.etd!==s.baselineEtd?'revised-date':'')+'">'+sd(s.etd)+'</b>')}${kv('Loaded on vessel',dt(s.actualDeparture))}${kv('Baseline → current ETA',sd(s.baselineEta)+' → <b class="'+(s.eta!==s.baselineEta?'revised-date':'')+'">'+sd(s.eta)+'</b>')}${kv('India port arrival',dt(s.actualArrival))}${kv('Final BL',s.blNumber?esc(s.blNumber)+' · '+dt(s.blDate):badge('Pending after vessel loading','amber'))}${kv('Insurance',s.insurance?badge('Completed','green'):s.blNumber?badge('Pending after final BL','amber'):badge('Awaiting final BL','dark'))}</div>${rv?.flag?`<div style="margin:12px 18px">${note(`<b>Freight warning:</b> booked USD ${rv.booked.toFixed(0)} vs latest weekly USD ${rv.market.toFixed(0)}. Difference +USD ${rv.difference.toFixed(0)} exceeds the USD ${state.settings.freightWarningUsd} threshold. Check whether cancellation / rebooking is still feasible.`,'warn')}</div>`:''}<div class="shipping-milestones">${milestones.map(m=>`<div class="ship-milestone ${m.actualDate?'done':m.estimatedDate?'active':''}"><span>${m.actualDate?icon('check',11):''}</span><div><b>${esc(m.label)}</b><small>${m.actualDate?dt(m.actualDate):m.estimatedDate?'Est. '+dt(m.estimatedDate):'Pending'}${m.location?' · '+esc(m.location):''}</small></div></div>`).join('')}</div>${s.alterations.length?`<div style="margin:12px 18px">${note(s.alterations.length+' specification/artwork alteration(s) remain visible for production / receipt verification.','warn')}</div>`:''}${missing.length&&!s.actualDeparture?`<div style="margin:12px 18px">${note('Before vessel loading: '+esc(missing.join(', ').replaceAll('_',' ')),'warn')}</div>`:''}${s.actualDeparture&&!s.blNumber?`<div style="margin:12px 18px">${note('Next required shipping action: record and verify the final BL.','warn')}</div>`:''}${s.blNumber&&!s.insurance?.insuredAt?`<div style="margin:12px 18px">${note('Next required shipping action: complete shipment insurance under the company master policy.','warn')}</div>`:''}<div class="ship-actions">${ed&&open&&s.bookingStatus==='PLANNED'?button('Book container','container-book',{id:o.id,shipment:s.id},'small primary','check'):''}${ed&&open&&s.bookingStatus==='BOOKED'?button('Container released','container-release',{id:o.id,shipment:s.id},'small primary','check'):''}${ed&&open&&!s.actualArrival?button('Tracking milestone','tracking-milestone',{id:o.id,shipment:s.id},'small','edit'):''}${ed&&open&&!s.actualArrival?button('Update ETD / ETA','shipment-update',{id:o.id,shipment:s.id},'small','edit'):''}${ed?button('Upload document','document',{id:o.id,shipment:s.id},'small','upload'):''}${ed&&open&&!s.actualDeparture?button('Verify BL draft (optional)','bl-draft',{id:o.id,shipment:s.id},'small','file'):''}${ed&&open&&!s.actualDeparture?button('Loaded on vessel','dispatch',{id:o.id,shipment:s.id},'small primary','ship'):''}${ed&&open&&s.actualDeparture&&!s.blNumber?button('Final BL / verify','bl',{id:o.id,shipment:s.id},'small primary','file'):''}${ed&&open&&s.blNumber&&!s.insurance?.insuredAt?button('Complete insurance','insurance',{id:o.id,shipment:s.id},'small primary','file'):''}${ed&&s.actualDeparture&&s.blNumber&&s.insurance?.insuredAt&&!s.actualArrival?button('India port arrival','arrival',{id:o.id,shipment:s.id},'small primary','check'):''}${canApprove(user)&&open&&!s.actualDeparture?button('Cancel allocation','cancel-shipment',{id:o.id,shipment:s.id},'small danger'):''}</div>${s.lastForwarderStatus?`<div class="panel-footer"><b>Latest forwarder Excel:</b> ${esc(s.lastForwarderStatus)} · ${dt(s.lastForwarderUpdateAt)}</div>`:''}</div>`;}
function orderShipments(o){const q=shipmentTotals(o);return note(`<div class="flex spread wrap"><span>${q.required} ordered · ${q.allocated} allocated · ${q.departed} departed · ${q.arrived} port-arrived.</span>${canEdit(user,o)?button('Plan shipment','shipment',{id:o.id},'small primary','plus'):''}</div>`)+`<div class="gap"></div>${o.shipments.map(s=>shipmentCard(o,s)).join('')||`<div class="panel">${empty('No shipments planned','Container booking can precede production completion.','ship')}</div>`}`;}
function orderDocuments(o){return `<div class="panel">${ph('Order and shipment evidence','Actual selected files with order / shipment / revision references.',canEdit(user,o)?button('Upload document','document',{id:o.id},'small primary','upload'):'')}<div class="document-list">${o.documents.map(d=>`<div class="doc-card"><div class="doc-symbol">${icon('file',18)}</div><div style="min-width:0;flex:1"><h3 title="${esc(d.name)}">${esc(d.name)}</h3><p>${esc(d.type.replaceAll('_',' '))}<br>Rev ${d.revision} · ${sd(d.uploadedAt)}<br>${esc(d.uploadedBy)}</p></div><button class="icon-button" data-action="file" data-file="${d.fileId}" aria-label="Download evidence">${icon('download',13)}</button></div>`).join('')||empty('No files uploaded')}</div><div class="panel-footer">Shipment-specific regulatory requirements must be confirmed before live use; this is not a legal compliance certificate.</div></div>`;}
function orderHistory(o){const events=state.events.filter(e=>e.entityType==='order'&&e.entityId===o.id).slice().reverse();return `<div class="panel">${ph('One continuous order history',`${events.length} entries · earlier records are never silently replaced.`,canEdit(user,o)?button('Log interaction','note',{id:o.id},'small primary','plus'):'')}<div class="timeline">${events.map(e=>`<div class="timeline-event"><div class="timeline-marker">${icon(e.action.includes('PAYMENT')?'money':e.action.includes('APPROV')?'check':'history',12)}</div><div class="timeline-content"><div class="event-top"><span>${esc(e.actorName)} · ${esc(e.source||'User action')}</span><span>${dt(e.at)} · ${e.at.slice(11,16)} UTC</span></div><p><b>${esc(e.action.replaceAll('_',' '))}</b><br>${esc(e.summary)}</p>${e.oldValue||e.newValue?`<details><summary>View previous and new values</summary><pre>${esc(JSON.stringify({previous:e.oldValue,updated:e.newValue},null,2))}</pre></details>`:''}${canEdit(user,o)?button('Add correction note','note',{id:o.id,event:e.id},'small ghost'):''}</div></div>`).join('')}</div></div>`;}
function taskTable(rows){return `<div class="table-wrap"><table><thead><tr><th>Task / order</th><th>Due</th><th>Owner</th><th>Status</th><th></th></tr></thead><tbody>${rows.map(({o,t})=>{const late=!t.completedAt&&t.due<isoDay();return `<tr><td class="strong">${esc(t.title)}<div class="sub"><a href="#/order/${o.id}">${esc(o.number)}</a></div></td><td class="${late?'due-red':''}">${dt(t.due)}</td><td>${esc(owner(t.ownerId??t.owner).replace('Demo ',''))}</td><td>${badge(t.completedAt?'Completed':late?'Overdue':t.due===isoDay()?'Today':'Upcoming',t.completedAt?'green':late?'red':'amber')}</td><td>${!t.completedAt&&canEdit(user,o)?button('Record outcome','task-complete',{id:o.id,task:t.id},'small','check'):button('Open','open-order',{id:o.id},'small ghost','arrow')}</td></tr>`;}).join('')||`<tr><td colspan="5">${empty('No follow-ups in this view','Each order has its own task schedule.','clock')}</td></tr>`}</tbody></table></div>`;}
function shippingTrackingPanel(rows){const batches=state.shippingImports||[];return `<div class="kpi-grid">${kpi('Active consignments',rows.filter(({s})=>s.status!=='ARRIVED'&&s.status!=='CANCELLED').length,'Ref-based manual tracking','ship')}${kpi('Booked / released',rows.filter(({s})=>['BOOKED','RELEASED'].includes(s.bookingStatus)).length,'Before vessel loading','box')}${kpi('On vessel / transit',rows.filter(({s})=>!!s.actualDeparture&&!s.actualArrival).length,'Vessel & voyage recorded','ship')}${kpi('Weekly tracking uploads',batches.length,'Previous status history retained','history')}</div><div class="panel" style="margin-bottom:20px">${ph('Weekly forwarding-agent report','Upload the VJ-style Excel. Ref is the primary match key; earliest planned ETD/ETA remain fixed.',canCreate(user)?button('Upload weekly tracking Excel','tracking-import',{},'small primary','upload'):'')}<div class="panel-body"><p class="small muted">Recognized fields: Supplier Name, Volume, Arrival Month, Invoice No, BL No, ETD, ETA, Status, Ref and Telex Status. Exact Ref matches are applied only after preview/confirmation.</p>${batches.slice(-3).reverse().map(b=>`<div class="history-row"><b>${esc(b.filename)}</b><span>${esc(b.statusDate||'')}</span><span>${b.matched} matched · ${b.unmatched} unmatched</span><span>${dt(b.at)}</span></div>`).join('')||'<p class="small muted">No weekly tracking file has been committed yet.</p>'}</div></div>${rows.map(({o,s})=>shipmentCard(o,s)).join('')||`<div class="panel">${empty('No shipments in this view','Plan shipments from issued purchase orders.','ship')}</div>`}`;}
function freightRatesPanel(){const all=state.freightRates||[],keys=[...new Set(all.map(r=>r.routeKey))],latest=keys.map(k=>all.filter(r=>r.routeKey===k).sort((a,b)=>(Number(a.sequence||0)-Number(b.sequence||0))||String(a.importedAt).localeCompare(String(b.importedAt))).at(-1)).filter(Boolean);return `<div class="kpi-grid">${kpi('Tracked freight routes',keys.length,'Exact route + via + destination + container type','ship')}${kpi('Latest benchmark rows',latest.length,'O/F + forwarding-agent charge','money')}${kpi('Agent-charge rule','USD 60 / 120','< 3,000 = 60 · ≥ 3,000 = 120','money')}${kpi('Rate warning threshold','USD '+state.settings.freightWarningUsd,'Booked freight > final benchmark by more than threshold','alert')}</div><div class="panel">${ph('Weekly freight buy-rate benchmark','Final benchmark = Ocean Freight + Agent Charge. Historical snapshots are never overwritten.',canCreate(user)?button('Upload weekly rate sheet','rate-import',{},'small primary','upload'):'')}<div class="table-wrap"><table><thead><tr><th>Route</th><th>Container</th><th>Week</th><th class="right">O/F USD</th><th class="right">Agent</th><th class="right">Final benchmark</th><th>Schedule</th><th>Trend</th></tr></thead><tbody>${latest.map(r=>{const tr=freightTrendFor(state,r.routeKey),agent=Number(r.agentChargeUsd??(Number(r.rateUsd)<3000?60:120)),benchmark=Number(r.benchmarkUsd??Number(r.rateUsd)+agent);return `<tr><td class="strong">${esc(r.origin)}${r.via?' via '+esc(r.via):''} → ${esc(r.destination)}</td><td>${esc(r.containerType)}</td><td>${esc(r.weekCode)}</td><td class="right">USD ${Number(r.rateUsd).toLocaleString('en-IN')}</td><td class="right">USD ${agent.toLocaleString('en-IN')}</td><td class="right strong">USD ${benchmark.toLocaleString('en-IN')}</td><td>${esc(r.schedule||'—')}</td><td>${badge(tr.direction,tr.direction==='RISING'?'red':tr.direction==='FALLING'?'green':'dark')}</td></tr>`;}).join('')||`<tr><td colspan="8">${empty('No freight rates','Upload the weekly forwarding-agent buy-rate sheet.','money')}</td></tr>`}</tbody></table></div></div>`;}
function freightTrendsPanel(){const all=state.freightRates||[],keys=[...new Set(all.map(r=>r.routeKey))];return `<div class="panel">${ph('Freight price trend & advance-booking watch','Trend uses the final benchmark (O/F + agent charge) and keeps every exact route separate.')}<div class="trend-grid">${keys.map(k=>{const tr=freightTrendFor(state,k),last=tr.recent.at(-1);const pending=visibleOrders().filter(o=>o.productionStartedAt&&!o.shipments.some(s=>s.status!=='CANCELLED'&&s.rateRouteKey===k)&&!o.productionCompletedAt).length;const latest=last?Number(last.benchmarkUsd??Number(last.rateUsd)+(Number(last.rateUsd)<3000?60:120)):null;return `<div class="trend-card"><div class="flex spread"><b>${esc(k.replaceAll('|',' · '))}</b>${badge(tr.direction,tr.direction==='RISING'?'red':tr.direction==='FALLING'?'green':'dark')}</div><div class="trend-value">${latest!==null?'USD '+latest.toLocaleString('en-IN'):'—'}</div><div class="sub">Latest final benchmark · O/F ${last?'USD '+Number(last.rateUsd).toLocaleString('en-IN'):'—'} + agent ${last?'USD '+Number(last.agentChargeUsd??(Number(last.rateUsd)<3000?60:120)).toLocaleString('en-IN'):'—'}</div><div class="sub" style="margin-top:7px">${tr.recent.map(r=>esc(r.weekCode)+': '+Number(r.benchmarkUsd??Number(r.rateUsd)+(Number(r.rateUsd)<3000?60:120)).toLocaleString('en-IN')).join(' · ')||'Only one snapshot available'}</div>${tr.direction==='RISING'&&pending?note(`${pending} active production order(s) on this exact route have no matching advance booking. Consider early booking while final benchmark rates are rising.`,'warn'):''}</div>`;}).join('')||empty('No rate history')}</div></div>`;}
function shipmentsView(){const rows=visibleOrders().flatMap(o=>o.shipments.map(s=>({o,s}))).filter(({s})=>!ui.status||s.status===ui.status),tabs=[['tracking','Container tracking'],['rates','Weekly freight rates'],['trends','Freight trends']];const content=ui.shippingTab==='rates'?freightRatesPanel():ui.shippingTab==='trends'?freightTrendsPanel():shippingTrackingPanel(rows);return head('LAE Import / Shipping','Shipping & freight control','Pre-production sample → bulk QC → production completion → booking/release → structured China legs → vessel → India port. Weekly Excel is the manual tracking heartbeat.')+`<div class="tabs">${tabs.map(([v,l])=>`<button class="tab ${ui.shippingTab===v?'active':''}" data-action="shipping-tab" data-value="${v}">${l}</button>`).join('')}</div>`+content;}

function tasksView(){const rows=visibleOrders().flatMap(o=>o.tasks.map(t=>({o,t}))).filter(({t})=>ui.status==='ALL'||!t.completedAt).sort((a,b)=>a.t.due.localeCompare(b.t.due));const open=rows.filter(({t})=>!t.completedAt),flags=allFlags();return head('LAE Import / Tasks','Tasks & follow-ups','Record supplier outcomes and reasons. A late completion does not erase its delay.')+`<div class="kpi-grid">${kpi('Open tasks',open.length,'Independent per order','clock')}${kpi('Due today',open.filter(({t})=>t.due===isoDay()).length,'Outcome and remarks required','calendar')}${kpi('Overdue tasks',open.filter(({t})=>t.due<isoDay()).length,'Visible until action is recorded','alert',true)}${kpi('Orders with critical flags',new Set(flags.filter(f=>f.level==='critical').map(f=>f.orderId)).size,'Planning, payment and execution','orders')}</div><div class="grid-main"><div class="panel">${ph('Purchase-team worklist','Weekly recurring follow-ups plus manually added work.',`<select id="task-status" class="select-small"><option value="OPEN" ${ui.status!=='ALL'?'selected':''}>Open tasks</option><option value="ALL" ${ui.status==='ALL'?'selected':''}>All tasks & outcomes</option></select>`)}${taskTable(rows)}</div><div class="panel">${ph('Red flags & advance warnings','Causes remain attributable to the responsible party.')}<div style="max-height:700px;overflow:auto">${flagList(flags,200)}</div></div></div>`;}
function paymentsView(){const os=recordOrders(),ps=state.payments.filter(p=>p.allocations.some(a=>os.some(o=>o.id===a.orderId)));return head('LAE Import / Financial follow-up','Payments & settlement','Purchase reports payments already made. This website never initiates a bank transfer.',canCreate(user)?button('Record payment','payment',{},'primary','plus'):'')+`<div class="kpi-grid">${kpi('Recorded remittances',ps.length,'Each bank reference counted once','money')}${kpi('Awaiting supplier receipt',ps.filter(p=>p.status!=='VOID').flatMap(p=>p.allocations).filter(a=>a.realizedMinor===null).length,'Invoice-currency realization','clock')}${kpi('Arrived, not settled',os.filter(o=>orderStatus(o)==='PORT_ARRIVED'&&financials(state,o).status!=='SETTLED').length,'Financial follow-up remains open','alert',true)}${kpi('Orders with payments',new Set(ps.flatMap(p=>p.allocations.map(a=>a.orderId))).size,'Original-order balances, not offsets','orders')}</div><div class="panel">${ph('Remittance register','Captured bank rates stay fixed. Live/reference rates never rewrite past payments.')}<div class="table-wrap"><table><thead><tr><th>Bank reference</th><th>Supplier / orders</th><th>Payment date</th><th class="right">Remittance</th><th class="right">Indian bank rate</th><th class="right">USD to RMB (BOC)</th><th>State</th><th>Evidence</th></tr></thead><tbody>${ps.slice().reverse().map(p=>`<tr><td class="mono">${esc(p.reference)}</td><td>${esc(state.vendors.find(v=>v.id===p.vendorId)?.code)}<div class="sub">${p.allocations.map(a=>`<a href="#/order/${a.orderId}">${esc(getOrder(a.orderId)?.number)}</a>`).join(' · ')}</div></td><td>${dt(p.date)}</td><td class="right strong">${formatMoney(p.amountMinor,p.currency)}</td><td class="right">${esc(bocRateText(p.inrRate))}<div class="sub">${esc(currencyPairLabel(p.currency,'INR'))}</div></td><td class="right">${esc(bocRateText(p.bocUsdRmbRate))||'&#8212;'}</td><td>${badge(p.status,p.status==='VOID'?'red':p.status==='ACKNOWLEDGED'?'green':'amber')}</td><td>${evidenceButtons(p,'Receipt')}${canPerformApproval(user,'VOID_PAYMENT','LAE_IMPORT',null,state)&&p.status!=='VOID'&&!p.allocations.some(a=>getOrder(a.orderId)?.deletedAt)?button('Void entry','void-payment',{payment:p.id},'small ghost'):''}</td></tr>`).join('')||`<tr><td colspan="8">${empty('No remittances recorded')}</td></tr>`}</tbody></table></div></div><div class="gap"></div><div class="panel">${ph('Order-by-order settlement','A consolidated supplier view does not transfer credits between orders.')}<div class="table-wrap"><table><thead><tr><th>Order</th><th>Operational stage</th><th class="right">Obligation</th><th class="right">Realized</th><th class="right">Balance</th><th>Financial status</th></tr></thead><tbody>${os.map(o=>{const f=financials(state,o);return `<tr class="row-click" data-action="open-order" data-id="${o.id}"><td class="code-link">${esc(o.number)}</td><td>${sb(o)}</td><td class="right">${formatMoney(f.total,o.currency)}</td><td class="right">${formatMoney(f.realized,o.currency)}</td><td class="right strong">${formatMoney(f.balance,o.currency)}</td><td>${badge(f.status,f.status==='SETTLED'?'green':'amber')}</td></tr>`;}).join('')}</tbody></table></div></div>`;}
function documentsView(){const rows=visibleOrders().flatMap(o=>o.shipments.filter(s=>s.status!=='CANCELLED').map(s=>({o,s})));return head('LAE Import / Quality & evidence','QC & shipping document control','Bulk-production QC is the production gate. Shipping then follows container release → vessel loading → final BL verification → insurance → India port arrival.')+`<div class="kpi-grid">${kpi('Linked evidence records',visibleOrders().reduce((n,o)=>n+o.documents.length,0),'PO, PI, confirmations, SWIFT, QC, BL and insurance','file')}${kpi('Bulk QC pending',visibleOrders().filter(o=>o.productionStartedAt&&!o.productionCompletedAt&&o.bulkQc?.result!=='PASS').length,'Blocks production completion','alert',true)}${kpi('Pre-vessel docs pending',rows.filter(({o,s})=>!s.actualDeparture&&shippingDocReadiness(o,s).length).length,'Commercial invoice + packing list','alert',true)}${kpi('Post-vessel compliance complete',rows.filter(({s})=>s.actualDeparture&&s.blNumber&&s.insurance?.insuredAt).length,'Final BL + insurance','check')}</div><div class="panel">${ph('Shipment evidence checklist','BL draft verification remains optional. Final BL and insurance are completed after Loaded on Vessel in the current workflow.')}<div class="table-wrap"><table><thead><tr><th>Order / shipment</th><th>Bulk QC</th><th>Commercial invoice</th><th>Packing list</th><th>Loaded on vessel</th><th>Final BL</th><th>Insurance</th><th></th></tr></thead><tbody>${rows.map(({o,s})=>`<tr><td><a class="code-link" href="#/order/${o.id}">${esc(o.number)}</a><div class="sub">${esc(s.number)} · ${esc(s.forwarderRef||'Ref pending')}</div></td><td>${badge(o.bulkQc?.result||'PENDING',o.bulkQc?.result==='PASS'?'green':o.bulkQc?.result==='ISSUES'?'red':'amber')}</td>${['COMMERCIAL_INVOICE','PACKING_LIST'].map(t=>`<td>${badge(hasDoc(o,t,s.id)?'Uploaded':'Pending',hasDoc(o,t,s.id)?'green':'amber')}</td>`).join('')}<td>${badge(s.actualDeparture?'Confirmed':'Pending',s.actualDeparture?'green':'amber')}</td><td>${badge(s.blNumber?'Verified':'Pending',s.blNumber?'green':'amber')}</td><td>${badge(s.insurance?.insuredAt?'Insured':'Pending',s.insurance?.insuredAt?'green':'amber')}</td><td>${button('Open','open-order',{id:o.id},'small ghost','arrow')}</td></tr>`).join('')}</tbody></table></div></div>`;}
function vendorsView(){const vs=state.vendors.filter(v=>v.scopes.some(s=>scopeAllowed(user,s))).filter(v=>!ui.search||[v.name,v.code,v.fixedSupplierCode,v.vendorSerial,v.fullReference,v.contact].join(' ').toLowerCase().includes(ui.search.toLowerCase()));const fixedCounts={};state.vendors.forEach(v=>{const c=key(v.fixedSupplierCode||'');if(c)fixedCounts[c]=(fixedCounts[c]||0)+1;});const duplicateFixed=[...new Set(state.vendors.filter(v=>fixedCounts[key(v.fixedSupplierCode||'')]>1).map(v=>v.fixedSupplierCode))];return head('Libraries / Vendor master','Vendor code master','Final supplier code list imported. Purchase uses Vendor Serial + fixed supplier code as the stable reference.',canApprove(user)?button('Payment terms','terms-master',{},'ghost')+button('Add vendor','vendor-edit',{},'primary','plus')+button('Upload vendors','vendor-import',{},'','upload'):'')+note('Loaded from supplier code masters.xlsx. Code rule: V01 is the vendor serial; SWAC is the fixed supplier code; full vendor reference is V01-SWAC. The 4-letter fixed code alone is not unique, so the system treats serial + fixed code as the unique key. Purchase still uses only ACTIVE vendors for PO creation.','blue')+`<div class="gap"></div><div class="kpi-grid">${kpi('Vendor code masters',state.vendors.length,'Final uploaded supplier list','users')}${kpi('Active suppliers',state.vendors.filter(v=>v.status==='ACTIVE'&&v.kind==='SUPPLIER').length,'Eligible for PO after item mapping','check')}${kpi('Duplicate fixed codes',duplicateFixed.length,duplicateFixed.join(' · ')||'None','alert',duplicateFixed.length>0)}${kpi('Vendor imports',(state.vendorImports||[]).length,'Source files retained','upload')}</div><div class="panel"><div class="toolbar"><div class="filters"><input id="view-search" value="${esc(ui.search)}" placeholder="Search supplier, V01-SWAC or SWAC" aria-label="Search vendor">${badge(vs.length+' records','dark')}</div></div><div class="table-wrap"><table><thead><tr><th>Vendor reference</th><th>Vendor name</th><th>Fixed code</th><th>Party type</th><th>Status</th><th>Commercial defaults</th><th>Port / TAT reference</th><th></th></tr></thead><tbody>${vs.map(v=>`<tr><td class="strong mono">${esc(v.fullReference||v.code)}<div class="sub">${esc(v.vendorSerial||'—')} + ${esc(v.fixedSupplierCode||'—')} ${v.codeLocked?'· locked':''}</div></td><td class="strong">${esc(v.name)}${referencePages.caption('vendors',v.id)}<div class="sub">${esc(v.country||'')}</div></td><td>${badge(esc(v.fixedSupplierCode||v.code),fixedCounts[key(v.fixedSupplierCode||'')]>1?'amber':'dark')}</td><td>${badge(v.kind==='LOGISTICS'?'Logistics':'Product supplier',v.kind==='LOGISTICS'?'blue':'dark')}</td><td>${badge(v.status,v.status==='ACTIVE'?'green':'red')}</td><td>${v.kind==='LOGISTICS'?'—':('Price '+esc(v.defaultPriceListCurrency||v.currency||'CNY')+' · Bill '+esc(v.defaultBillingCurrency||v.currency||'USD')+' · '+esc(v.defaultPaymentMethod||'TT'))}<div class="sub">${esc(v.kind==='LOGISTICS'?(v.logisticsPaymentTerms||'Logistics terms not recorded'):(paymentTermsFor(state,'SUPPLIER',true).find(t=>t.id===v.defaultTerms)?.name||v.paymentTermsText||v.defaultTerms||''))}</div></td><td>${esc(v.defaultExportPort||'—')}<div class="sub">${v.kind==='LOGISTICS'?'Logistics partner':v.productionDays+' reference days'}</div></td><td>${button('VMS profile','nav',{to:'vms/'+v.id},'small')}${button('View','vendor-view',{vendor:v.id},'small')}${canApprove(user)?button('Edit','vendor-edit',{vendor:v.id},'small ghost','edit'):canCreate(user)?button('Request update','vendor-request',{vendor:v.id},'small ghost'):''}</td></tr>`).join('')||`<tr><td colspan="8">${empty('No vendor records')}</td></tr>`}</tbody></table></div></div><div class="gap"></div><div class="panel">${ph('Vendor import history','Uploaded master lists are retained for audit and future reconciliation.')}<div class="table-wrap"><table><thead><tr><th>File</th><th>Rows</th><th>Mapping rule</th><th>Imported by</th><th>Notes</th></tr></thead><tbody>${(state.vendorImports||[]).map(b=>`<tr><td class="strong">${esc(b.filename)} ${b.sourceFileId?button('Source file','file',{file:b.sourceFileId},'small ghost','file'):''}<div class="sub mono">${esc(b.source||'')}</div></td><td>${b.count}</td><td>${esc(b.mappingVersion)}</td><td>${esc(b.by)}<div class="sub">${dt(b.at)}</div></td><td>${esc(b.notes||'')}</td></tr>`).join('')||`<tr><td colspan="5">${empty('No vendor import batches')}</td></tr>`}</tbody></table></div></div>`;}
function priceListsView(){
 const suppliers=state.vendors.filter(v=>v.kind==='SUPPLIER'&&v.status==='ACTIVE'&&v.scopes.some(s=>scopeAllowed(user,s)));
 const rows=(state.priceLists||[]).filter(p=>p.status==='APPROVED').map(p=>({p,v:state.vendors.find(v=>v.id===p.vendorId),b:state.bases.find(b=>b.id===p.baseId)})).filter(x=>x.v&&x.b).filter(x=>!ui.search||[x.v.code,x.v.name,x.b.code,x.b.productName,x.p.currency].join(' ').toLowerCase().includes(ui.search.toLowerCase()));
 const cny=rows.filter(x=>x.p.currency==='CNY').length,usd=rows.filter(x=>x.p.currency==='USD').length;
 return head('LAE Import / Commercial master','Supplier price lists','Supplier price is maintained against the Base Item Code. GJ / KD / TT ERP Item Codes inherit it unless a controlled brand adjustment is added later.',canCreate(user)?button('Add / revise price','price-edit',{},'primary','plus')+button('Upload prices','price-import',{},'','upload')+button('Import history','price-import-history',{},'small','history'):'')+
 note('Base Item Code is the price-list key. A PO starts with the Base Item Code, then brand-wise quantities create ERP Item Codes such as GJ-PW62RG, KD-PW62RG and TT-PW62RG.','blue')+
 `<div class="gap"></div><div class="kpi-grid">${kpi('Suppliers with prices',new Set(rows.map(x=>x.v.id)).size,'Current base-product price lists','users')}${kpi('Current RMB/CNY prices',cny,'Base Item Code prices','money')}${kpi('Current USD prices',usd,'Can coexist with CNY','money')}${kpi('Base price revisions',(state.priceLists||[]).length,'Full history retained','history')}</div>`+
 `<div class="panel"><div class="toolbar"><div class="filters"><input id="view-search" value="${esc(ui.search)}" placeholder="Search supplier, Base Item Code or currency" aria-label="Search supplier price list">${badge(rows.length+' current prices','dark')}</div></div><div class="table-wrap"><table><thead><tr><th>Supplier</th><th>Base Item Code / product</th><th>ERP variants</th><th>Currency</th><th class="right">Current unit price</th><th>Effective</th><th>Revision</th><th></th></tr></thead><tbody>${rows.sort((a,b)=>(a.v.code+a.b.code+a.p.currency).localeCompare(b.v.code+b.b.code+b.p.currency)).map(({p,v,b})=>{const history=(state.priceLists||[]).filter(x=>x.vendorId===v.id&&x.baseId===b.id&&x.currency===p.currency).length;const erps=state.items.filter(i=>i.baseId===b.id).map(i=>i.code).join(' · ');return `<tr><td class="strong">${esc(v.code)}<div class="sub">${esc(v.name)}</div></td><td><span class="code-link">${esc(b.code)}</span><div class="sub">${esc(b.productName||'')}</div></td><td><div class="sub">${esc(erps)}</div></td><td>${badge(p.currency==='CNY'?'RMB / CNY':'USD',p.currency==='CNY'?'green':'blue')}</td><td class="right strong">${formatMoney(p.unitPriceMinor,p.currency)}</td><td>${dt(p.effectiveDate)}</td><td>Rev ${p.revision||1}<div class="sub">${history} stored</div></td><td>${canCreate(user)?button('Revise','price-edit',{price:p.id},'small','edit'):''}${button('History','price-history',{vendor:v.id,base:b.id,currency:p.currency},'small ghost','history')}</td></tr>`;}).join('')||`<tr><td colspan="8">${empty('No supplier prices yet','Add a supplier Base Item price in RMB/CNY or USD.','money')}</td></tr>`}</tbody></table></div></div>`+
 `<div class="gap"></div><div class="panel">${ph('Suppliers ready for base-product pricing','Prices are inherited by ERP Item Codes under the same Base Item Code.')}<div class="panel-body"><div class="flex wrap">${suppliers.map(v=>{const count=(state.priceLists||[]).filter(p=>p.vendorId===v.id&&p.status==='APPROVED').length;return `<span class="badge ${count?'green':'dark'}">${esc(v.code)} · ${count} current</span>`;}).join('')}</div></div></div>`;
}
function itemsView(){const tabs=[['bases','Base Item Master'],['items','ERP Item Codes'],['categories','LAE categories'],['imports','Import history']];let body='';const items=state.items.filter(i=>scopeAllowed(user,i.scope)&&(!ui.category||i.category===ui.category)&&(!ui.search||[i.code,i.baseItemCode,i.name,i.description].join(' ').toLowerCase().includes(ui.search.toLowerCase())));const bases=state.bases.filter(b=>scopeAllowed(user,b.scope)&&(!ui.category||b.category===ui.category)&&(!ui.search||[b.code,b.productName,b.description,b.category].join(' ').toLowerCase().includes(ui.search.toLowerCase())));
 if(ui.masterTab==='bases')body=note('The first sheet of ITEM MASTER.xlsx is the final Base Item Master. Base Item Code is the parent product used for PLM roll-up, supplier price list, complaint consolidation and PO selection.','blue')+`<div class="gap"></div><div class="panel"><div class="toolbar"><div class="filters"><input id="view-search" value="${esc(ui.search)}" placeholder="Search Base Item Code or description"><select id="category-filter"><option value="">All LAE categories</option>${state.categories.map(c=>`<option ${ui.category===c.name?'selected':''}>${esc(c.name)}</option>`).join('')}</select>${badge(bases.length+' base items','dark')}</div></div><div class="table-wrap"><table><thead><tr><th>Base Item Code</th><th>Product</th><th>Category / grade</th><th>Supplier</th><th>Reference production</th><th>ERP Item Codes</th><th>PLM</th></tr></thead><tbody>${bases.slice((ui.page-1)*15,ui.page*15).map(b=>{const v=state.vendors.find(v=>v.id===b.vendorId),erps=state.items.filter(i=>i.baseId===b.id);return `<tr><td><button class="link-button mono" data-action="open-product" data-id="${b.id}">${esc(b.code)}</button>${referencePages.caption('bases',b.id)}</td><td class="strong">${esc(b.productName||'')}<div class="sub">${esc(b.description||'')}</div></td><td>${esc(b.category)}<div class="sub">${esc(b.grade||'')}</div></td><td class="mono">${esc(v?.code||'—')}</td><td>${b.productionDays||'—'} days<div class="sub">Product-level reference; supplier master is fallback.</div></td><td><div class="sub">${erps.map(i=>esc(i.code)).join(' · ')}</div></td><td>${latestApprovedSpec(state,b.id)?badge('Approved v'+latestApprovedSpec(state,b.id).version,'green'):badge('Tech spec pending','amber')}</td></tr>`;}).join('')}</tbody></table></div>${pageButtons(bases.length,15)}</div>`;
 if(ui.masterTab==='items')body=note('ERP Item Code = Brand Prefix + “-” + Base Item Code. These codes are used for brand-wise PO quantities and all post-PO operational tracking.','blue')+`<div class="gap"></div><div class="panel"><div class="toolbar"><div class="filters"><input id="view-search" value="${esc(ui.search)}" placeholder="Search ERP Item Code"><select id="category-filter"><option value="">All LAE categories</option>${state.categories.map(c=>`<option ${ui.category===c.name?'selected':''}>${esc(c.name)}</option>`).join('')}</select>${badge(items.length+' ERP items','dark')}</div></div><div class="table-wrap"><table><thead><tr><th>ERP Item Code</th><th>Base Item Code</th><th>Brand</th><th>Product</th><th>Supplier</th><th>Post-PO controls</th></tr></thead><tbody>${items.slice((ui.page-1)*18,ui.page*18).map(i=>`<tr><td class="code-link mono">${esc(i.code)}${referencePages.caption('items',i.id)}</td><td><button class="link-button" data-action="open-product" data-id="${i.baseId}">${esc(i.baseItemCode||state.bases.find(b=>b.id===i.baseId)?.code||'—')}</button></td><td>${esc(i.brand)}<div class="sub">${esc(i.brandPrefix||'')}</div></td><td>${esc(i.name)}<div class="sub">${esc(i.category)}</div></td><td class="mono">${esc(i.vendorCode||'')}</td><td><div class="sub">Artwork · colour/outlook · packing · QC observations · shipment allocation · complaints</div>${canCreate(user)?button(i.baseId?'Edit mapping':'Set up item','item-edit',{item:i.id},'small ghost','edit'):''}</td></tr>`).join('')}</tbody></table></div>${pageButtons(items.length,18)}</div>`;
 if(ui.masterTab==='categories')body=`<div class="panel">${ph('LAE category master',`${state.categories.length} configurable categories.`)}<div class="table-wrap"><table><thead><tr><th>Category</th><th>Base items</th><th>ERP items</th><th>State</th></tr></thead><tbody>${state.categories.map(c=>`<tr><td class="strong">${esc(c.name)}</td><td>${state.bases.filter(b=>b.category===c.name).length}</td><td>${state.items.filter(i=>i.category===c.name).length}</td><td>${badge(c.active?'Active':'Inactive',c.active?'green':'dark')}</td></tr>`).join('')}</tbody></table></div></div>`;
 if(ui.masterTab==='imports')body=`<div class="panel">${ph('Retained import batches','Final item master and source files are retained for audit.')}<div class="table-wrap"><table><thead><tr><th>Filename / batch</th><th>Uploader</th><th>Date</th><th>Rows</th><th>Mapping</th></tr></thead><tbody>${state.imports.map(b=>`<tr><td class="strong">${esc(b.filename)} ${b.sourceFileId?button('Source file','file',{file:b.sourceFileId},'small ghost','file'):''}<div class="sub mono">${b.id}</div></td><td>${esc(b.by)}</td><td>${dt(b.at)}</td><td>${b.count}</td><td>${esc(b.mappingVersion)}<div class="sub">${esc(b.notes||'')}</div></td></tr>`).join('')}</tbody></table></div></div>`;
 return head('Libraries / Item master','Item & ERP code library','Base Item Code is the product parent. ERP Item Codes use GJ-, KD- and TT- brand mappings.',canCreate(user)?button('Add ERP item','item-edit',{},'primary','plus')+button('Upload item master','import',{},'','upload'):'')+`<div class="kpi-grid">${kpi('Base Item Codes',state.bases.length,'Final first-sheet item list','box')}${kpi('ERP Item Codes',state.items.length,'3 brand variants per base item','orders')}${kpi('Base prices',(state.priceLists||[]).filter(p=>p.status==='APPROVED').length,'Filtered to final Base Item Master','money')}${kpi('Suppliers',new Set(state.bases.map(b=>b.vendorId)).size,'One supplier per Base Item Code','users')}</div><div class="tabs">${tabs.map(([v,l])=>`<button class="tab ${ui.masterTab===v?'active':''}" data-action="master-tab" data-value="${v}">${l}</button>`).join('')}</div>`+body;
}

const getBase=id=>state.bases.find(b=>b.id===id);
const baseVendor=b=>state.vendors.find(v=>v.id===b?.vendorId);
