function specFieldsHtml(b,spec){
 const tpl=state.plmTemplates?.find(t=>t.id===b.templateId)||templateForCategory(state,b.category);if(!tpl)return `<pre class="spec-text">${esc(spec?.description||'No specification')}</pre>`;
 const groups=[...new Set(tpl.fields.filter(f=>f.active!==false).map(f=>f.group))];
 return groups.map(g=>`<div class="form-section">${esc(g)}</div><div class="kv-grid">${tpl.fields.filter(f=>f.active!==false&&f.group===g).map(f=>{const tags=[f.required?'required':'',f.qcPreproduction?'PP sample QC':'',f.qcBulk?'bulk QC':'',f.poPrint?'PO':'',f.supplierConfirm?'supplier confirm':''].filter(Boolean).map(x=>`<span class="badge dark" style="margin-left:4px">${esc(x)}</span>`).join('');return kv(f.label,esc(spec?.fieldValues?.[f.key]||'—')+(tags?`<div class="sub" style="margin-top:6px">${tags}</div>`:''));}).join('')}</div>`).join('');
}
function checklistHtml(title,rows){return `<div class="panel">${ph(title,rows.length+' checks generated from the approved PLM template')}<div class="table-wrap"><table><thead><tr><th>Group</th><th>Check</th><th>Approved value</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(r.group)}</td><td class="strong">${esc(r.label)}</td><td>${esc(r.value||'—')}</td></tr>`).join('')||`<tr><td colspan="3">${empty('No checklist fields configured')}</td></tr>`}</tbody></table></div></div>`;}
function lineageHtml(b){const prev=getBase(b.previousBaseId),next=state.bases.filter(x=>x.previousBaseId===b.id);return `<div class="lineage"><div>${prev?`<button class="button small ghost" data-action="open-product" data-id="${prev.id}">${esc(prev.code)}</button><div class="sub">Previous model</div>`:'<span class="badge dark">Origin model</span>'}</div><div class="lineage-arrow">${icon('arrow',18)}</div><div><b class="mono">${esc(b.code)}</b><div class="sub">Current</div></div>${next.map(n=>`<div class="lineage-arrow">${icon('arrow',18)}</div><div><button class="button small ghost" data-action="open-product" data-id="${n.id}">${esc(n.code)}</button><div class="sub">Successor</div></div>`).join('')}</div>`;}
function plmView(){
 const tabs=[['products','Products'],['changes','Change approvals'],['templates','Templates'],['variants','ERP item variants'],['complaints','Complaints'],['audit','PLM audit']];
 const bases=state.bases.filter(b=>scopeAllowed(user,b.scope)).filter(b=>!ui.search||[b.code,b.productName,b.category,b.family,baseVendor(b)?.code].join(' ').toLowerCase().includes(ui.search.toLowerCase()));
 const pendingSpecs=state.bases.flatMap(b=>b.specifications.filter(s=>s.status==='PENDING').map(s=>({b,s})));
 const pendingDelta=state.items.filter(i=>i.baseId&&i.brandDeltaStatus==='PENDING');
 const pendingArt=state.items.flatMap(i=>(i.artworkRevisions||[]).filter(a=>a.status==='PENDING').map(a=>({i,a})));
 let body='';
 if(ui.plmTab==='products')body=`<div class="panel"><div class="toolbar"><div class="filters"><input id="view-search" value="${esc(ui.search)}" placeholder="Search model, family, category or supplier"><span class="badge dark">${bases.length} products</span></div>${canCreate(user)?button('Create PLM product','plm-base',{},'small primary','plus'):''}</div><div class="table-wrap"><table><thead><tr><th>Product / family</th><th>Category</th><th>Supplier</th><th>Approved version</th><th>Pending version</th><th>Brand SKUs</th><th>Status</th></tr></thead><tbody>${bases.map(b=>{const cur=latestApprovedSpec(state,b.id),pen=pendingSpec(state,b.id),variants=state.items.filter(i=>i.baseId===b.id);return `<tr class="row-click" data-action="open-product" data-id="${b.id}"><td><span class="code-link">${esc(b.code)}</span><div class="sub">${esc(b.productName||b.code)} · ${esc(b.family||'—')}</div></td><td>${esc(b.category||'—')}</td><td><span class="mono">${esc(baseVendor(b)?.code||'—')}</span><div class="sub">${esc(baseVendor(b)?.name||'')}</div></td><td>${cur?badge('v'+cur.version,'green'):'—'}</td><td>${pen?badge('v'+pen.version+' pending','amber'):'—'}</td><td>${variants.length}<div class="sub">${variants.slice(0,3).map(i=>esc(i.code)).join(' · ')}</div></td><td>${badge(b.lifecycleStatus||'DRAFT',(b.lifecycleStatus||'DRAFT')==='ACTIVE'?'green':'dark')}</td></tr>`;}).join('')||`<tr><td colspan="7">${empty('No PLM products','Create a base product and then release an approved technical revision.')}</td></tr>`}</tbody></table></div></div>`;
 if(ui.plmTab==='changes')body=`<div class="kpi-grid">${kpi('Technical revisions',pendingSpecs.length,'Awaiting configured approver','history')}${kpi('Brand deltas',pendingDelta.length,'Packaging / decal differences','edit')}${kpi('Artwork revisions',pendingArt.length,'Brand artwork pending','file')}${kpi('Total pending',pendingSpecs.length+pendingDelta.length+pendingArt.length,'No pending record is silently used in a PO','alert',pendingSpecs.length+pendingDelta.length+pendingArt.length>0)}</div><div class="panel">${ph('Approval queue','Configured approval makes technical / brand requirements available for procurement.')}<div class="table-wrap"><table><thead><tr><th>Type</th><th>Product / SKU</th><th>Revision</th><th>Requested by</th><th>Reason / change</th><th>Action</th></tr></thead><tbody>${pendingSpecs.map(({b,s})=>`<tr><td>${badge('Technical','blue')}</td><td><button class="link-button" data-action="open-product" data-id="${b.id}">${esc(b.code)}</button></td><td>v${esc(s.version)}</td><td>${esc(s.by)}</td><td>${esc(s.changeSummary||s.reason)}</td><td>${(canPerformApproval(user,'APPROVE_SPEC','LAE_IMPORT',null,state)?button('Approve','approve-spec',{base:b.id,spec:s.id},'small primary','check'):'')+(canPerformApproval(user,'REJECT_SPEC','LAE_IMPORT',null,state)?button('Reject','reject-spec',{base:b.id,spec:s.id},'small ghost'):'')+button('Review','open-product',{id:b.id},'small')}</td></tr>`).join('')}${pendingDelta.map(i=>`<tr><td>${badge('Brand delta','dark')}</td><td>${esc(i.code)}<div class="sub">${esc(i.brand)}</div></td><td>Current proposal</td><td>${esc(i.brandDeltaRequestedBy||'Purchase')}</td><td>${esc(brandDeltaSummary(i.brandDelta).slice(0,180))}</td><td>${canPerformApproval(user,'APPROVE_BRAND_DELTA','LAE_IMPORT',null,state)?button('Approve','approve-brand-delta',{item:i.id},'small primary','check'):button('Open product','open-product',{id:i.baseId},'small')}</td></tr>`).join('')}${pendingArt.map(({i,a})=>`<tr><td>${badge('Artwork','amber')}</td><td>${esc(i.code)}<div class="sub">${esc(i.brand)}</div></td><td>${esc(a.revision)}</td><td>${esc(a.by)}</td><td>${esc(a.remarks)}</td><td>${canPerformApproval(user,'APPROVE_BRAND_ARTWORK','LAE_IMPORT',null,state)?button('Approve','approve-brand-artwork',{item:i.id,artwork:a.id},'small primary','check'):button('Open product','open-product',{id:i.baseId},'small')}</td></tr>`).join('')||`<tr><td colspan="6">${empty('No pending PLM approvals','All current product and brand requirements are resolved.','check')}</td></tr>`}</tbody></table></div></div>`;
 if(ui.plmTab==='templates')body=note('Templates define category-specific technical fields. The detailed Power Weeder template is revised from the supplied technical-spec spreadsheet; price and quantity remain outside PLM.','blue')+`<div class="gap"></div><div class="grid-two">${(state.plmTemplates||[]).map(t=>`<div class="panel">${ph(esc(t.name),t.category==='*'?'Fallback for categories without a dedicated template':esc(t.category)+(t.source?' · sample-derived':''),canProductApprove(user)?button('Add field','template-field',{template:t.id},'small','plus'):'')}<div class="panel-body">${[...new Set(t.fields.filter(f=>f.active!==false).map(f=>f.group))].map(g=>`<div class="form-section">${esc(g)}</div>${t.fields.filter(f=>f.active!==false&&f.group===g).map(f=>`<div class="flex spread" style="padding:8px 0;border-bottom:1px solid #eef4f0;gap:12px"><span>${esc(f.label)} ${f.required?'<b style="color:#b57153">*</b>':''}<div class="sub">${f.qcPreproduction?badge('PP QC','green'):''} ${f.qcBulk?badge('Bulk QC','blue'):''} ${f.poPrint?badge('PO','dark'):''} ${f.supplierConfirm?badge('Supplier confirm','amber'):''}</div></span><span class="sub mono">${esc(f.key)} · ${esc(f.type)}</span></div>`).join('')}`).join('')}${t.source?`<div class="gap"></div>${note('Template source: '+esc(t.source),'blue')}`:''}</div></div>`).join('')}</div>`;
 if(ui.plmTab==='variants'){const variants=state.items.filter(i=>i.baseId&&i.brand);body=`<div class="panel">${ph('Brand variants','Technical requirements inherit from the base product. Only brand-specific differences are stored here.')}<div class="table-wrap"><table><thead><tr><th>Brand SKU</th><th>Base</th><th>Brand</th><th>Brand differences</th><th>Approval</th><th>Artwork</th><th></th></tr></thead><tbody>${variants.map(i=>{const a=approvedBrandArtwork(i);return `<tr><td class="code-link">${esc(i.code)}</td><td><button class="link-button" data-action="open-product" data-id="${i.baseId}">${esc(getBase(i.baseId)?.code)}</button></td><td>${esc(i.brand)}</td><td style="max-width:360px;white-space:pre-wrap">${esc(brandDeltaSummary(i.brandDelta)||i.artworkNotes||'No differences recorded')}</td><td>${badge(i.brandDeltaStatus||'NOT CONFIGURED',i.brandDeltaStatus==='APPROVED'?'green':i.brandDeltaStatus==='PENDING'?'amber':'dark')}</td><td>${a?badge(a.revision,'green'):(i.artworkRevisions||[]).some(x=>x.status==='PENDING')?badge('Pending','amber'):'—'}</td><td>${canCreate(user)||canProductApprove(user)?button('Edit differences','brand-delta',{item:i.id},'small ghost','edit')+button('New artwork','brand-artwork',{item:i.id},'small','upload'):''}</td></tr>`;}).join('')}</tbody></table></div></div>`;}
 if(ui.plmTab==='complaints'){const cs=state.complaints||[],baseRows=state.bases.map(b=>({b,c:complaintCounts(b.id)})).filter(x=>x.c.total>0||!ui.search||[x.b.code,x.b.productName].join(' ').toLowerCase().includes(ui.search.toLowerCase()));body=`<div class="kpi-grid">${kpi('Total complaints',cs.length,'All brands rolled to Base Item Code','alert',cs.some(c=>c.severity==='CRITICAL'))}${kpi('Critical',cs.filter(c=>c.severity==='CRITICAL').length,'Highest severity','alert',cs.some(c=>c.severity==='CRITICAL'))}${kpi('Major',cs.filter(c=>c.severity==='MAJOR').length,'Major issues','history')}${kpi('Affected base products',new Set(cs.map(c=>c.baseId)).size,'Consolidated product view','box')}</div><div class="panel">${ph('Complaint roll-up by Base Item Code','Each complaint is recorded against an ERP Item Code; totals consolidate to the common Base Item Code.',canCreate(user)?button('Add complaint','complaint',{},'small primary','plus'):'')}<div class="table-wrap"><table><thead><tr><th>Base Item Code</th><th>Product</th><th class="right">GJ</th><th class="right">KD</th><th class="right">TT</th><th class="right">Total</th><th>Severity mix</th></tr></thead><tbody>${baseRows.map(({b,c})=>`<tr class="row-click" data-action="open-product" data-id="${b.id}"><td class="code-link">${esc(b.code)}</td><td>${esc(b.productName)}</td><td class="right">${c.byBrand.GJ}</td><td class="right">${c.byBrand.KD}</td><td class="right">${c.byBrand.TT}</td><td class="right strong">${c.total}</td><td>${c.severity.CRITICAL?badge(c.severity.CRITICAL+' critical','red'):''} ${c.severity.MAJOR?badge(c.severity.MAJOR+' major','amber'):''} ${c.severity.MODERATE?badge(c.severity.MODERATE+' moderate','blue'):''} ${c.severity.MINOR?badge(c.severity.MINOR+' minor','dark'):''}</td></tr>`).join('')||`<tr><td colspan="7">${empty('No complaints recorded','Complaints will be stored against ERP Item Codes and consolidated here.')}</td></tr>`}</tbody></table></div></div>`;}
 if(ui.plmTab==='audit'){const ev=state.events.filter(e=>['base','item','template'].includes(e.entityType)).slice().reverse();body=`<div class="panel">${ph('PLM edit and approval log','Corrections create new events; earlier audit records are not rewritten.')}<div class="timeline">${ev.map(e=>`<div class="timeline-event"><div class="timeline-dot"></div><div><div class="flex spread"><b>${esc(e.action.replaceAll('_',' '))}</b><span class="sub">${dt(e.at)}</span></div><p>${esc(e.summary)}</p><small>${esc(e.actorName)} · ${esc(e.entityType)} · <span class="mono">${esc(e.entityId)}</span></small></div></div>`).join('')||empty('No PLM events yet')}</div></div>`;}
 return head('Product Lifecycle Management','PLM · What exactly are we buying?','Base-product technical control with ERP Item Code artwork/outlook, complaint roll-up and Product Manager approval.',canCreate(user)?button('Create product','plm-base',{},'primary','plus'):'')+`<div class="kpi-grid">${kpi('Base products',state.bases.length,'One supplier per base SKU','box')}${kpi('Approved revisions',state.bases.flatMap(b=>b.specifications).filter(s=>s.status==='APPROVED').length,'Released technical versions','check')}${kpi('Pending approvals',pendingSpecs.length+pendingDelta.length+pendingArt.length,'Product Manager queue','clock')}${kpi('ERP Item Codes',state.items.filter(i=>i.baseId&&i.brand).length,'GJ / KD / TT operational codes','orders')}</div><div class="tabs">${tabs.map(([v,l])=>`<button class="tab ${ui.plmTab===v?'active':''}" data-action="plm-tab" data-value="${v}">${l}</button>`).join('')}</div>`+body;
}
function productView(){const b=getBase(ui.orderId);if(!b)return head('PLM','Product not found','The requested PLM product is unavailable.');const v=baseVendor(b),cur=latestApprovedSpec(state,b.id),pen=pendingSpec(state,b.id),tpl=state.plmTemplates?.find(t=>t.id===b.templateId)||templateForCategory(state,b.category),variants=state.items.filter(i=>i.baseId===b.id),history=state.events.filter(e=>(e.entityType==='base'&&e.entityId===b.id)||(e.entityType==='item'&&variants.some(i=>i.id===e.entityId))).slice().reverse();const docs=b.specifications.flatMap(sp=>(sp.documents||[]).map(d=>({...d,version:sp.version,status:sp.status}))),cmp=complaintCounts(b.id);
 return head('PLM / '+esc(b.category||'LAE'),esc(b.code)+' · '+esc(b.productName||b.code),esc(b.family||'')+' · '+esc(v?.name||'Supplier not linked'),(canCreate(user)||canProductApprove(user)?button('New technical revision','plm-revision',{base:b.id},'primary','plus'):'')+(canCreate(user)?button('Create successor model','plm-successor',{base:b.id},'','arrow'):''))+`${pen?note(`<b>New technical version ${esc(pen.version)} is pending approval.</b> Unapproved revisions never update an issued PO. New PO issue follows the pending-version policy in Settings.`,'warn'):''}<div class="grid-main"><div class="panel">${ph('Product identity & lineage','Significant change creates a new product code; minor/internal change creates a version.')}<div class="panel-body"><div class="kv-grid">${kv('Base product code','<span class="mono strong">'+esc(b.code)+'</span>')}${kv('Product category',esc(b.category||'—'))}${kv('Product family',esc(b.family||'—'))}${kv('VMS supplier',esc(v?.code||'—')+' · '+esc(v?.name||''))}${kv('PLM template',esc(tpl?.name||'Generic'))}${kv('Lifecycle',badge(b.lifecycleStatus||'DRAFT',(b.lifecycleStatus||'DRAFT')==='ACTIVE'?'green':'dark'))}${kv('Creation reason',esc(b.creationReason||'—'))}${kv('Current approved version',cur?badge('v'+cur.version,'green'):'No approved version')}</div><div class="gap"></div>${lineageHtml(b)}</div></div><div class="panel">${ph('Procurement readiness','Approved technical versions are selected when available. Brand-specific requirements need approval.')}<div class="panel-body">${cur?note(`<b>Technical v${esc(cur.version)}</b> approved by ${esc(cur.approvedBy||'—')} on ${dt(cur.approvedAt)}.`,'blue'):note('PLM specification not available. A PO may proceed with a visible warning. Active ERP brand items and approved brand-specific requirements are still needed.','warn')}<div class="gap"></div><div class="kv-grid">${kv('Brand SKUs',variants.length)}${kv('Approved brand deltas',variants.filter(i=>i.brandDeltaStatus==='APPROVED').length)}${kv('Pending brand changes',variants.filter(i=>i.brandDeltaStatus==='PENDING').length)}${kv('Open POs',visibleOrders().filter(o=>o.lines.some(l=>l.baseId===b.id)&&!['PORT_ARRIVED','SHORT_CLOSED'].includes(orderStatus(o))).length)}</div></div></div></div><div class="gap"></div><div class="panel">${ph('Current approved technical specification',cur?`Version ${esc(cur.version)} · ${esc(cur.reason)}`:'No released version')}${cur?`<div class="panel-body">${specFieldsHtml(b,cur)}<div class="form-section">Change context</div><div class="kv-grid">${kv('Change summary',esc(cur.changeSummary||'—'))}${kv('Requested by',esc(cur.requestedBy||cur.by||'—'))}${kv('Approved by',esc(cur.approvedBy||'—'))}</div></div>`:`<div class="panel-body">${empty('No approved specification','Create a revision and approve it using the configured approval access.')}</div>`}</div>${cur&&tpl?`<div class="gap"></div><div class="grid-two">${checklistHtml('Pre-production sample QC checklist',qcChecklistForSpec(tpl,cur.fieldValues,'PREPRODUCTION'))}${checklistHtml('Bulk-production QC checklist',qcChecklistForSpec(tpl,cur.fieldValues,'BULK'))}</div><div class="gap"></div><div class="grid-two">${checklistHtml('PO technical package',poFieldsForSpec(tpl,cur.fieldValues))}${checklistHtml('Supplier confirmation package',supplierConfirmationFields(tpl,cur.fieldValues))}</div>`:''}<div class="gap"></div><div class="panel">${ph('Technical revision history','Every value set remains associated with its version code.')}<div class="table-wrap"><table><thead><tr><th>Version</th><th>Status</th><th>Change / reason</th><th>Requested</th><th>Decision</th><th>Documents</th><th></th></tr></thead><tbody>${b.specifications.slice().reverse().map(sp=>`<tr><td class="strong">v${esc(sp.version)}</td><td>${badge(sp.status,specTone(sp))}</td><td>${esc(sp.changeSummary||sp.reason)}<div class="sub">${esc(sp.reason)}</div></td><td>${esc(sp.by)}<div class="sub">${dt(sp.at)}</div></td><td>${sp.status==='APPROVED'?esc(sp.approvedBy)+' · '+dt(sp.approvedAt):sp.status==='REJECTED'?esc(sp.rejectedBy)+' · '+esc(sp.rejectionRemarks):'Awaiting configured approver'}</td><td>${(sp.documents||[]).map(d=>button(d.name,'file',{file:d.fileId},'small ghost','file')).join(' ')||'—'}</td><td>${sp.status==='PENDING'?(canPerformApproval(user,'APPROVE_SPEC','LAE_IMPORT',null,state)?button('Approve','approve-spec',{base:b.id,spec:sp.id},'small primary','check'):'')+(canPerformApproval(user,'REJECT_SPEC','LAE_IMPORT',null,state)?button('Reject','reject-spec',{base:b.id,spec:sp.id},'small ghost'):''):''}</td></tr>`).join('')}</tbody></table></div></div><div class="gap"></div><div class="panel">${ph('Brand-specific variants','Technical specification is inherited from '+esc(b.code)+'. Store only superficial differences such as decals, labels and packaging.',canCreate(user)?button('Add ERP item','item-edit',{base:b.id},'small primary','plus'):'')}<div class="table-wrap"><table><thead><tr><th>Brand SKU</th><th>Brand</th><th>Differences</th><th>Delta approval</th><th>Artwork revisions</th><th></th></tr></thead><tbody>${variants.map(i=>{const art=approvedBrandArtwork(i),pending=(i.artworkRevisions||[]).find(a=>a.status==='PENDING');return `<tr><td class="code-link">${esc(i.code)}</td><td>${esc(i.brand)}</td><td style="white-space:pre-wrap;max-width:420px">${esc(brandDeltaSummary(i.brandDelta)||i.artworkNotes||'No brand-specific change recorded.')}</td><td>${badge(i.brandDeltaStatus||'NOT CONFIGURED',i.brandDeltaStatus==='APPROVED'?'green':i.brandDeltaStatus==='PENDING'?'amber':'dark')}<div class="sub">${i.brandDeltaApprovedBy?esc(i.brandDeltaApprovedBy):'Final approval pending'}</div></td><td>${art?badge(art.revision,'green')+' '+evidenceButtons(art,'Open artwork'):'—'} ${pending?badge(pending.revision+' pending','amber')+' '+evidenceButtons(pending,'Review artwork'):''}</td><td>${canApprove(user)?button('Edit item master','item-edit',{item:i.id},'small ghost','edit'):''}${canCreate(user)||canProductApprove(user)?button('Edit delta','brand-delta',{item:i.id},'small ghost','edit')+button('New artwork','brand-artwork',{item:i.id},'small','upload'):''}${i.brandDeltaStatus==='PENDING'&&canPerformApproval(user,'APPROVE_BRAND_DELTA','LAE_IMPORT',null,state)?button('Approve delta','approve-brand-delta',{item:i.id},'small primary','check'):''}${pending&&canPerformApproval(user,'APPROVE_BRAND_ARTWORK','LAE_IMPORT',null,state)?button('Approve artwork','approve-brand-artwork',{item:i.id,artwork:pending.id},'small primary','check'):''}</td></tr>`;}).join('')||`<tr><td colspan="6">${empty('No brand variants','Map operational brand SKUs from the Item Master.')}</td></tr>`}</tbody></table></div></div><div class="gap"></div><div class="panel">${ph('After-sales complaints · Base Item '+esc(b.code),cmp.total+' total across all ERP Item Codes',canCreate(user)?button('Add complaint','complaint',{base:b.id},'small primary','plus'):'')}<div class="kpi-grid" style="padding:18px;margin:0">${kpi('GJ',cmp.byBrand.GJ,'GJ-'+b.code,'alert')}${kpi('KD',cmp.byBrand.KD,'KD-'+b.code,'alert')}${kpi('TT',cmp.byBrand.TT,'TT-'+b.code,'alert')}${kpi('Total',cmp.total,'Base product total','alert',cmp.severity.CRITICAL>0)}</div><div class="table-wrap"><table><thead><tr><th>ERP Item Code</th><th>Severity</th><th>Complaint</th><th>Recorded</th><th>Documents</th></tr></thead><tbody>${cmp.rows.slice().reverse().map(c=>`<tr><td class="code-link">${esc(c.erpItemCode)}</td><td>${badge(c.severity,c.severity==='CRITICAL'?'red':c.severity==='MAJOR'?'amber':c.severity==='MODERATE'?'blue':'dark')}</td><td>${esc(c.summary)}${referencePages.caption('complaints',c.id)}<div class="sub">${esc(c.remarks||'')}</div></td><td>${dt(c.at)}<div class="sub">${esc(c.by||'')}</div></td><td>${(c.documents||[]).map(d=>button(d.name,'file',{file:d.fileId},'small ghost','file')).join(' ')||'—'}</td></tr>`).join('')||`<tr><td colspan="5">${empty('No complaints for this base product')}</td></tr>`}</tbody></table></div></div><div class="gap"></div><div class="grid-two"><div class="panel">${ph('PLM documents','Drawings, specifications, test reports and technical evidence attached to revisions.')}<div class="panel-body">${docs.map(d=>`<div class="doc-card"><div>${icon('file',16)}<div><b>${esc(d.name)}</b><small>Technical v${esc(d.version)} · ${esc(d.status)}</small></div></div>${button('Open','file',{file:d.fileId},'small ghost','download')}</div>`).join('')||empty('No technical documents attached')}</div></div><div class="panel">${ph('PLM activity log','Visible author, time and reason for every edit / approval.')}<div class="panel-body">${history.slice(0,12).map(e=>`<div class="release-row"><div><b class="mono">${dt(e.at)}</b><small>${esc(e.actorName)}</small></div><div><b>${esc(e.action.replaceAll('_',' '))}</b><small>${esc(e.summary)}</small></div></div>`).join('')||empty('No activity yet')}</div></div></div>`;
}

const EDITS=[['SW-0001','Overall purchase website','Responsive shell, overview, division context, navigation and task dashboard.','web/app.mjs; web/styles.css'],['SW-0002','Order transaction controls','PO draft / approval / immutable issue snapshot, amendments and PI validation.','shared/domain.mjs'],['SW-0003','Payment follow-up','Milestone authorization, shipment allocations, USD/CNY realization and original-order balances.','shared/domain.mjs; web/app.mjs'],['SW-0004','Production, artwork & QC','Visible supplier commitments, separate artwork approval, change checks and dispatch hold.','shared/domain.mjs; web/app.mjs'],['SW-0005','Partial shipments','Shipment quantity control, baseline/current/actual dates, BL-triggered terms and port-arrival closure.','shared/domain.mjs'],['SW-0006','Master upload & evidence','Demo-source preservation, explicit brand/base mapping, XLSX/CSV preview and audited commit.','shared/source-items.mjs; web/app.mjs'],['SW-0007','Local pilot service','Authenticated sessions, scoped commands, protected files and transactional SQLite persistence.','server/index.mjs; server/store.mjs'],['SW-0008','Versioning & verification','Portable review build, source archive, release log and automated verification.','scripts/; tests/; docs/'],['SW-0009','PLM product architecture','Base product identity, product family, one-supplier link, model lineage and significant-change successor logic.','shared/domain.mjs; shared/plm.mjs; web/app.mjs'],['SW-0010','PLM revision workflow','Dynamic category templates, technical revision requests, Product Manager approval/rejection, documents and immutable PO snapshots.','shared/plm.mjs; shared/domain.mjs; web/app.mjs'],['SW-0011','Brand-specific PLM control','Brand SKU deltas, decals/packaging/labels, separate artwork revisions and Product Manager final approval.','shared/domain.mjs; web/app.mjs'],['SW-0012','PLM dashboards & audit','Product dashboard, approval queue, template manager, lineage view and visible PLM edit log.','web/app.mjs; web/styles.css'],['SW-0013','Shipping production gates','Mandatory pre-production sample approval and bulk-production QC before completion.','shared/domain.mjs; shared/seed.mjs; web/app.mjs'],['SW-0014','Container & compliance workflow','Container booked/released states, structured China legs, pre-dispatch QC, BL-draft verification, separate insurance, vessel/voyage and India-port arrival.','shared/domain.mjs; shared/shipping.mjs; web/app.mjs'],['SW-0015','Weekly forwarder tracking import','VJ-style Excel upload matched by forwarding-agent Ref; earliest planned ETD/ETA retained and revisions appended to tracking history.','shared/shipping.mjs; shared/domain.mjs; web/app.mjs'],['SW-0016','Freight benchmark & trends','Weekly buy-rate import, route-specific history, booked-vs-latest variance warning above USD 100 and advance-booking trend watch.','shared/shipping.mjs; shared/domain.mjs; web/app.mjs'],['SW-0017','Shipping verification & release control','Dedicated shipping browser checks using the user-supplied weekly tracking and rate workbooks; updated packaging and change logs.','tests/; docs/; scripts/build.mjs'],['SW-0018','Corporate visual theme','FarmingHub.in-inspired enterprise theme applied without changing workflow rules.','web/styles.css; web/app.mjs'],['SW-0019','Official RGB logo','Official Farming Hub RGB logo applied to sidebar, login, favicon and printable PO header.','web/app.mjs; web/index.html; web/styles.css'],['SW-0020','Brand guideline compliance','Uploaded Farming Hub Brand Guidelines made the visual source of truth: #204321 / #C5DA41, approved secondary palette, AmsiPro-first typography and controlled logo/brand elements.','web/styles.css; web/app.mjs; web/assets/farming-hub-logo.png; docs/brand/*'],['SW-0021','Supplier RMB/USD price-list master','Current product-wise supplier prices in RMB/CNY or USD with revision history and retained superseded values.','shared/domain.mjs; shared/seed.mjs; web/app.mjs'],['SW-0022','PO price-list auto-fill & variance warning','Latest current supplier price auto-fills new PO lines; manual difference is allowed with visible warning and frozen price-list snapshot.','shared/domain.mjs; web/app.mjs; tests/'],['SW-0023','Visible PO-to-port workflow','Every mandatory gate is now a visible top timeline stage with the next required action beside Print PO.','shared/domain.mjs; web/app.mjs'],['SW-0024','Technical confirmation + payment stage','Supplier technical confirmation added after PI approval; initial payment is one visible milestone with SWIFT, bank reference, FX and automatic production-lead-time start.','shared/domain.mjs; web/app.mjs'],['SW-0025','Corrected production & shipping sequence','Pre-production sample moved after payment/lead-time start; pre-dispatch QC removed; vessel loading now precedes final BL and insurance; India-port closure requires BL + insurance.','shared/domain.mjs; shared/shipping.mjs; shared/seed.mjs; web/app.mjs'],['SW-0026','Step-by-step workflow testability','Separated sample completion from sample approval and extended the header next-action control through container booking, China inland tracking, CI/PL, vessel, final BL, insurance and India-port arrival.','shared/domain.mjs; web/app.mjs; tests/'],['SW-0027','Clean business-data baseline','Removed all seeded/demo vendors, items, PLM products, prices, orders, payments, shipments, documents, freight rates and import history while retaining system masters.','shared/clean-seed.mjs; scripts/build.mjs; tests/clean_browser_flow.py'],['SW-0028','Power Weeder detailed PLM template v2','User technical-spec spreadsheet mapped into structured engine, transmission, controls, wheel, blade, packing and technical-note fields. Price and quantity remain outside PLM.','shared/plm.mjs; docs/reference/Power_Weeder_Technical_Spec_Sample.xlsx'],['SW-0029','PLM downstream-control metadata','Technical fields can now be tagged for pre-production sample QC, bulk QC, PO technical package and supplier confirmation; product page shows generated checklists.','shared/plm.mjs; shared/domain.mjs; web/app.mjs'],['SW-0030','Structured brand variant specification','Brand delta expanded to sticker application, embossing, packaging and primary/secondary component-colour mapping while keeping functional changes in the base technical revision.','shared/plm.mjs; shared/domain.mjs; web/app.mjs'],['SW-0031','Vendor Master Library from final code list','supplier code masters.xlsx imported as the locked Vendor Code Master. Vendor Serial + fixed supplier code form the unique reference, e.g. V01-SWAC; the 4-letter code alone is allowed to repeat.','shared/clean-seed.mjs; web/app.mjs; docs/reference/Supplier_Code_Master_Final.xlsx'],['SW-0032','Item-master upload readiness against Vendor Library','Item Master remains empty until the next upload; importer now matches vendor references by full code, fixed code or serial for validation before PO use.','shared/domain.mjs; web/app.mjs'],['SW-0033','Supplier TAT override reason visibility','Supplier override-reason field appears only when the order commitment differs from the vendor reference production days.','web/app.mjs; shared/domain.mjs'],['SW-0034','Supplier commercial master from workbook','Payment terms, default payment method, price-list currency, billing currency, export port and reference production days imported from the user-updated supplier master.','shared/clean-seed.mjs; shared/domain.mjs; web/app.mjs'],['SW-0035','Terms-driven PO payment calculation','PO payment schedule now uses the vendor default payment term from the master; BL-based credit terms calculate due dates from final BL date.','shared/domain.mjs; web/app.mjs'],['SW-0036','Final Base Item Master + ERP Item Codes','ITEM MASTER first sheet loaded as the authoritative Base Item Master; GJ-, KD- and TT- ERP Item Codes generated under every valid base product.','shared/final-master-data.mjs; shared/clean-seed.mjs; web/app.mjs'],['SW-0037','Base-product price list import','PRICE LIST MASTER filtered to final Base Item Codes only; CNY/USD supplier prices stored against supplier + Base Item Code + currency and inherited by ERP Item Codes.','shared/final-master-data.mjs; shared/domain.mjs; web/app.mjs'],['SW-0038','Base-first brand-wise PO planning','PO entry now selects Base Item Code first, then GJ/KD/TT quantities; only positive quantities expand into ERP Item Code PO lines.','web/app.mjs; shared/domain.mjs'],['SW-0039','ERP complaints with base roll-up','After-sales complaints are recorded against ERP Item Code and aggregated to Base Item Code for product-level PLM analysis.','shared/domain.mjs; web/app.mjs'],['SW-0040','Historical freight trend + agent benchmark','Historical WEEKLY BUY RATE loaded; final benchmark = O/F + USD 60 below 3,000 or USD 120 at/above 3,000; booked-rate warning and trend use final benchmark.','shared/final-master-data.mjs; shared/shipping.mjs; web/app.mjs'],['SW-0042','Missing PLM warning bypass','If a Base Item has no approved PLM revision, PO submission/approval continues with a persistent warning and audit event; PLM is never falsely marked approved.','shared/domain.mjs; web/app.mjs; tests/plm_bypass.test.mjs']];
function managerAccessPanel(){if(!scopeAllowed(user,'LAE_IMPORT'))return '';const missing=APPROVAL_STAGES.filter(s=>!approvalRoles(state,s.command).includes(user.role));return '<div class="panel">'+ph('Your workflow access',missing.length?missing.length+' approval stages need a configured approver.':'All purchase approval stages are available to your role.')+'<div class="panel-body">'+(missing.length?note(user.role==='MANAGER'?'An administrator can enable Independent Manager workflow in Approval controls. Existing evidence and readiness checks remain.':'Your administrator can review the assigned approval roles. Evidence, division and assigned-order limits still apply.','warn'):note('You can complete purchase, product, artwork, payment and sample approvals within your division.','blue'))+'<div class="table-wrap"><table><thead><tr><th>Approval stage</th><th>Your access</th><th>Allowed roles</th></tr></thead><tbody>'+APPROVAL_STAGES.map(s=>'<tr><td>'+esc(s.label)+'</td><td>'+badge(approvalRoles(state,s.command).includes(user.role)?'Allowed':'Not assigned',approvalRoles(state,s.command).includes(user.role)?'green':'amber')+'</td><td>'+['ADMIN',...approvalRoles(state,s.command)].map(userRoleLabel).map(esc).join(', ')+'</td></tr>').join('')+'</tbody></table></div></div></div><div class="gap"></div>';}
function masterImportBody(kind,rows){return button('Download template','master-import-template',{kind},'small','download')+'<p class="small muted">'+(kind==='vendor'?'Use full vendor reference codes. Existing identities stay locked. Payment terms use the IDs shown in the vendor form. Blank optional cells clear that value on update.':'Use full vendor code and Base Item Code. Currency: USD or CNY. Effective date: YYYY-MM-DD. Prices append to the existing price history; no PO is repriced.')+'</p>'+field('masterFile','Choose XLSX / CSV','','file',{attrs:'id="master-import-file" accept=".xlsx,.csv"'})+(ui.masterFile?'<p class="sub">'+esc(ui.masterFile.name)+'</p>':'')+(rows.length?'<div class="table-wrap"><table><thead><tr><th>Row</th><th>Key</th><th>Result</th><th>Validation</th></tr></thead><tbody>'+rows.slice(0,20).map(r=>'<tr><td>'+r.row+'</td><td>'+esc(r.key)+'</td><td>'+badge(r.result,r.errors.length?'red':'green')+'</td><td>'+esc(r.errors.join('; '))+'<details><summary>Review values</summary><pre style="white-space:pre-wrap;overflow-wrap:anywhere">'+esc(JSON.stringify(r.payload,null,2))+'</pre></details></td></tr>').join('')+'</tbody></table></div><p class="small muted">Showing '+Math.min(20,rows.length)+' of '+rows.length+' rows. Any rejected row blocks the entire batch.</p>'+button('Export validation report','export-master-import',{},'small','download'):note('Select a completed template to validate before saving. No master changes happen during preview.','blue'));}
function entityAudit(type,id){const events=state.events.filter(e=>e.entityType===type&&e.entityId===id).slice().reverse();return '<div class="form-section">Change history</div>'+events.map(e=>'<details class="timeline-event"><summary><b>'+esc(e.action.replaceAll('_',' '))+'</b> · '+esc(e.actorName)+' · '+dt(e.at)+'</summary><p>'+esc(e.summary)+'</p><pre style="white-space:pre-wrap;overflow-wrap:anywhere">'+esc(JSON.stringify({previous:e.oldValue,updated:e.newValue},null,2))+'</pre></details>').join('')+(events.length?'':'<p class="small muted">No local change events retained for this record.</p>');}
function approvalControlsPanel(){if(user.role!=='ADMIN')return managerAccessPanel();const history=state.events.filter(e=>e.action==='APPROVAL_CONTROLS_UPDATED').slice().reverse();return '<div class="panel">'+ph('Approval controls','Manage who can approve each stage in LAE Import.',button('Manage approval controls','approval-controls',{},'primary','lock'))+'<div class="panel-body">'+note('Changes remain active until an administrator edits or restores them. There is no automatic September rule or expiry. Admin always retains approval access.','blue')+'<div class="gap"></div><div class="table-wrap"><table><thead><tr><th>Approval stage</th><th>Allowed roles</th></tr></thead><tbody>'+APPROVAL_STAGES.map(s=>'<tr><td>'+esc(s.label)+'<div class="sub">'+esc(s.group)+'</div></td><td>'+['ADMIN',...approvalRoles(state,s.command)].map(userRoleLabel).map(esc).join(', ')+(s.assignedExecutiveOnly?'<div class="sub">Executive: assigned orders only.</div>':'')+'</td></tr>').join('')+'</tbody></table></div><div class="gap"></div><h3>Approval control history</h3>'+(history.length?'<div class="table-wrap"><table><thead><tr><th>Date / administrator</th><th>Reason</th><th>Changes</th></tr></thead><tbody>'+history.map(e=>'<tr><td>'+esc(dt(e.at))+'<div class="sub">'+esc(e.actorName)+'</div></td><td>'+esc(e.newValue?.remarks||'')+'</td><td>'+APPROVAL_STAGES.filter(s=>JSON.stringify(e.oldValue?.stages?.[s.command]||s.roles)!==JSON.stringify(e.newValue?.stages?.[s.command]||[])).map(s=>esc(s.label)+': '+['ADMIN',...(e.oldValue?.stages?.[s.command]||s.roles)].map(userRoleLabel).map(esc).join(', ')+' &rarr; '+['ADMIN',...(e.newValue?.stages?.[s.command]||[])].map(userRoleLabel).map(esc).join(', ')).join('<br>')+'</td></tr>').join('')+'</tbody></table></div>':'<p class="small muted">Standard roles are active. No approval control changes recorded.</p>')+'</div></div><div class="gap"></div>';}
function approvalControlsModal(){return {title:'Approval controls',sub:'All approval stages / LAE Import',submit:'Save approval controls',wide:true,body:note('Selected roles can approve within their assigned division, including their own submissions. Sample approval and initial-payment completion retain assigned-order limits for Executives. Admin always remains enabled; Viewer cannot approve. Changes apply to new requests immediately, including pending orders, and stay active until changed. Existing approvals remain valid.','warn')+'<div class="gap"></div>'+button('Enable independent Manager workflow','manager-workflow-preset',{},'','check')+' '+button('Restore standard roles','restore-approval-defaults',{},'','history')+'<p class="small muted">Restore fills this form with the standard roles. Review and save to apply it.</p><div class="grid-two">'+APPROVAL_STAGES.map(s=>'<fieldset class="panel panel-body"><legend>'+esc(s.label)+'</legend><p class="small muted">'+esc(s.group)+(s.command==='COMPLETE_INITIAL_PAYMENT'?' / Records remittance and automatically authorizes initial milestones.':s.assignedExecutiveOnly?' / Executive must be assigned to the order.':'')+'</p><p class="small">Administrator: always allowed</p>'+APPROVAL_ASSIGNABLE_ROLES.map(role=>'<label style="display:block;margin:10px 0"><input type="checkbox" name="approval-'+s.command+'" value="'+role+'" '+(approvalRoles(state,s.command).includes(role)?'checked':'')+'> '+esc(userRoleLabel(role))+'</label>').join('')+'</fieldset>').join('')+'</div><div class="gap"></div>'+note('Supplier acknowledgements, PI verification, QC recording, shipping and settlement still require their existing evidence and readiness checks. These controls change approvers; they do not skip workflow stages.','blue')+field('remarks','Reason for approval control changes','','textarea',{required:true,full:true})+checkbox('confirm','I confirm these role permissions and understand that allowed users may approve their own submissions.')};}
function personalPreferencesPanel(){return '<div class="panel" id="personal-preferences">'+ph('My preferences','Minimal is the standard theme. These settings apply only to your login.')+'<div class="panel-body">'+checkbox('showPageGuides','Show page guides',personalPreferences(user).showPageGuides)+'<p class="small muted">Show page descriptions and expand guidance. The order timeline and mascot help stay available.</p><div class="gap"></div>'+button('Save preferences','save-preferences',{},'primary')+'</div></div><div class="gap"></div>';}
function settingsView(){return head('Administration','Users & settings','Create sign-in accounts and manage access by role and division.',!sandbox&&user.role==='ADMIN'?button('Create user','create-user',{},'primary','plus'):'')+referencePages.settingsLink()+personalPreferencesPanel()+approvalControlsPanel()+userAccessPanel()+`<div class="gap"></div><div class="grid-two"><div class="panel">${ph('Visible pilot policy defaults','These are review settings, not a signed-off production policy.',user.role==='ADMIN'?button('Edit','policy',{},'small','edit'):'')}<div class="panel-body"><div class="kv-grid">${kv('Advance warning',state.settings.warningDays+' days')}${kv('Container booking lead',state.settings.bookingLeadDays+' days')}${kv('Physical completion','Actual destination-port arrival')}${kv('Pending technical version',state.settings.allowPreviousApprovedSpec?'Previous approved revision allowed':'New issue held until resolved')}${kv('Commercial gate','PI + technical confirmation + artwork + initial payment')}${kv('Planning TAT','Manually entered total')}</div></div></div><div class="panel">${ph('Connections & local data','No live system has been altered.')}<div class="panel-body">${note('PLM is active in this pilot. Live VMS synchronization, ERP, warehouse receipts and carrier APIs are not connected. Existing VMS source is retained as a reference, not executed against your live database.','blue')}<div class="gap"></div>${button('View roadmap','nav',{to:'roadmap'},'','arrow')}<div class="gap"></div>${sandbox?button('Backup review data','backup',{},'','download')+' '+button('Reset demo','reset',{},'danger','history'):'<p class="small muted">Administrators can create users above. Database backup instructions are in docs/ADMINISTRATION.md.</p>'}</div></div></div><div class="gap"></div><div class="grid-two"><div class="panel">${ph('Payment method master','Supplier defaults currently use TT unless later changed.')}<div class="table-wrap"><table><thead><tr><th>Method</th><th>Description</th></tr></thead><tbody>${(state.paymentMethods||PAYMENT_METHODS).map(m=>`<tr><td class="strong">${esc(m.name)}</td><td>${esc(m.description||'')}</td></tr>`).join('')}</tbody></table></div></div><div class="panel">${ph('Port master','Export ports from the supplier master workbook plus the destination port.')}<div class="table-wrap"><table><thead><tr><th>Port</th><th>Country</th><th>Type</th></tr></thead><tbody>${(state.ports||PORTS).map(p=>`<tr><td class="strong">${esc(p.displayName||p.name)}</td><td>${esc(p.country)}</td><td>${badge(p.type,p.type==='EXPORT'?'green':'blue')}</td></tr>`).join('')}</tbody></table></div></div></div><div class="gap"></div><div class="panel">${ph('Port and route planning master','Route rows are references only; manual total planning TAT stays explicit.',canApprove(user)?button('Add route','route',{},'small','plus'):'')}<div class="table-wrap"><table><thead><tr><th>Route</th><th>Origin</th><th>Destination</th><th>Transit days</th><th></th></tr></thead><tbody>${state.routes.map(r=>`<tr><td>${esc(r.name)}<div class="sub">${esc(r.source)}</div></td><td>${esc(r.origin)}</td><td>${esc(r.destination)}</td><td>${r.transitDays}</td><td>${canApprove(user)?button('Edit','route',{route:r.id},'small'):''}</td></tr>`).join('')}</tbody></table></div></div>`;}
function versionsView(){return head('Governance / Change control','Version & software edit log','Software versions, requirement changes and business-record history are separate.',button('Export edit register','export-edits',{},'','download'))+`<div class="intro-banner"><div><div class="eyebrow" style="color:#9abc9d">Supplier commercial masters + detailed PLM + Shipping alpha</div><h2>Farming Hub Purchase Management · ${APP_VERSION}</h2><p>LAE Import workflow with supplier payment terms, default currencies, export ports, detailed PLM templates, price lists and the visible PO → India-port sequence. Not a production deployment.</p></div>${icon('history',35)}</div><div class="grid-two"><div class="panel">${ph('Source requirements retained')}<div class="panel-body">${note('The v0.2.0 requirements, later category/master additions labelled v0.1.1, detailed user decisions and existing VMS source are inputs. The out-of-order document numbers are not treated as a requirements rollback.')}<div class="gap"></div><p class="small muted">Development authorization: the instruction to begin the website and LAE Import workflow. Management UAT and deployment acceptance have not been recorded.</p></div></div><div class="panel">${ph('Build control')}<div class="panel-body"><div class="kv-grid">${kv('Software version',APP_VERSION)}${kv('Storage schema',state.schemaVersion)}${kv('Data transaction revision',state.revision)}${kv('Live integrations','Not enabled')}</div></div></div></div><div class="gap"></div><div class="panel">${ph('Implementation edit register','Each group maps to included source files.')}${EDITS.map(([id,n,s,f])=>`<div class="release-row"><div><b class="mono">${id}</b><small>v${APP_VERSION}</small></div><div><b>${n}</b><small>${s}</small><small class="mono">${f}</small></div>${badge('Built','green')}</div>`).join('')}<div class="panel-footer">See docs/TEST_REPORT.md for actual automated results and testing limitations. Demo transactions are not evidence of real staff activity.</div></div>`;}
function roadmapView(){return head('Controlled expansion','One website. LAE Import first.','Keep the detailed requirements without pretending later modules are already complete.')+`<div class="panel">${ph('Implementation sequence')}<div class="panel-body">${[['01','Overall shell and LAE Import alpha','Current build: manual PO, approvals, specification snapshots, PI, payments, follow-up, artwork/QC and shipments.'],['02','Live VMS integration and rollout controls','Validate native source / lockfiles, share live identities and vendor history, migrate real data, harden deployment and complete UAT.'],['03','Planning and container consolidation','Monthly Sales requirement, freeze, supplier consolidation, quotations, packing components, CBM and load planning.'],['04','ERP and other divisions','Complaint feedback is now captured by ERP Item Code and rolled up to Base Item Code. Future: ERP finance/receipts, LAE Domestic, Utility/Implements, carrier and messaging APIs.']].map(([n,t,s])=>`<div style="border-left:2px solid #d9e8dd;padding:0 0 27px 22px;margin-left:10px"><div class="eyebrow">${n}</div><h3>${t}</h3><p class="subtitle">${s}</p></div>`).join('')}</div></div>`;}
function userRoleLabel(role){return {ADMIN:'Administrator',MANAGER:'Purchase Manager',EXECUTIVE:'Purchase Executive',PRODUCT_MANAGER:'Product Manager',VIEWER:'Viewer'}[role]||role;}
function userRoleHelp(role){return {ADMIN:'Full access to all divisions, user creation and settings.',MANAGER:'Manage and approve purchases in assigned divisions. Approval controls determine approval access.',EXECUTIVE:'Create purchases and update orders assigned to this user.',PRODUCT_MANAGER:'Manage technical specifications, templates and artwork approvals in assigned divisions.',VIEWER:'Read records in assigned divisions. Cannot create or approve transactions.'}[role]||'';}
async function loadUserAccounts(){const actorId=user.id,request=(ui.accountRequest||0)+1;ui.accountRequest=request;ui.accountsError='';try{const r=await api('/users');if(user?.id!==actorId||ui.accountRequest!==request)return;ui.accounts=r.users;}catch(e){if(user?.id!==actorId||ui.accountRequest!==request)return;ui.accountsError=e.message;}if((ui.view==='settings'||ui.view==='vms'&&ui.vmsPage==='users')&&!ui.modal)render();}
function userAccessPanel(){const admin=user.role==='ADMIN'&&!sandbox;return `<div class="panel">${ph('User access portal',admin?'Create an account, then review its role and division access.':'Role controls the action; scope controls the records available.')}${sandbox?`<div class="panel-body">${note('This browser review uses sample profiles. Sign in to the hosted application as an administrator to create a real user account.','blue')}</div>`:''}${admin&&ui.accountsError?`<div class="panel-body">${note(esc(ui.accountsError),'warn')}${button('Refresh users','refresh-users',{},'small','history')}</div>`:''}<div class="table-wrap"><table><thead><tr><th>User / role</th>${admin?'<th>Email</th><th>Sign-in status</th>':''}${SCOPES.map(s=>`<th>${SCOPE_LABELS[s]}</th>`).join('')}</tr></thead><tbody>${state.users.map(u=>{const account=ui.accounts?.find(a=>a.id===u.id);return `<tr><td class="strong">${esc(u.name)}<div class="sub">${esc(userRoleLabel(u.role))}</div>${user.role==='ADMIN'&&u.id!==user.id?button('Change role','change-role',{user:u.id},'small ghost','edit'):''}</td>${admin?`<td>${esc(account?.email||(ui.accounts?'No sign-in account':'Loading…'))}</td><td>${account?badge(account.hasAccount?(account.active?'Active':'Inactive'):'Profile only',account.active?'green':'dark'):badge(ui.accounts?'Profile only':'Loading','dark')}</td>`:''}${SCOPES.map(s=>`<td><input type="checkbox" aria-label="${esc(u.name+' '+SCOPE_LABELS[s])}" data-user-scope="${u.id}" data-scope="${s}" ${u.role==='ADMIN'||u.scopes.includes(s)?'checked':''} ${user.role!=='ADMIN'||u.role==='ADMIN'?'disabled':''}></td>`).join('')}</tr>`;}).join('')}</tbody></table></div><div class="panel-footer">Administrators have access to all divisions. Only LAE Import currently has an operational workflow. Assignment changes are excluded from the business interaction log; new account creation and role changes are recorded. Role changes apply to existing sessions immediately. Your own administrator role cannot be changed here.</div></div>`;}
function userCreationModal(){return {title:'Create user',sub:'Set up an account for this purchase workspace.',submit:'Create user',wide:false,body:`<div class="form-grid">${field('name','Full name','','text',{required:true,attrs:'maxlength="120" autocomplete="name"'})}${field('email','Email address','','email',{required:true,attrs:'maxlength="254" autocomplete="off" autocapitalize="none"'})}${field('role','Role','EXECUTIVE','select',{required:true,full:true,options:USER_ROLES.map(role=>({value:role,label:userRoleLabel(role)}))})}<div class="full"><p class="small muted" id="new-user-role-hint">${esc(userRoleHelp('EXECUTIVE'))}</p></div>${field('password','Password','','password',{required:true,attrs:'minlength="12" maxlength="256" autocomplete="new-password"',hint:'Use 12–256 characters. Share the password with the user through your usual secure channel.'})}${field('confirmPassword','Confirm password','','password',{required:true,attrs:'minlength="12" maxlength="256" autocomplete="new-password"'})}</div><div class="form-section">Division access</div><div class="check-list">${SCOPES.map(scope=>checkbox('scopes',SCOPE_LABELS[scope],scope==='LAE_IMPORT',scope)).join('')}</div>${note('Select at least one division. Administrators have access to every division. LAE Domestic, Utility and Implements workflows are planned.','blue')}`};}
async function createUserFromForm(form,values){if(busy)return;if(sandbox||user.role!=='ADMIN')throw new Error('Administrator access is required to create users.');if(values.get('password')!==values.get('confirmPassword'))throw new Error('Passwords do not match.');const scopes=values.get('role')==='ADMIN'?[...SCOPES]:values.getAll('scopes');if(!scopes.length)throw new Error('Select at least one division.');busy=true;const submit=form.querySelector('[type=submit]');submit.disabled=true;try{const r=await api('/users',{method:'POST',body:JSON.stringify({name:values.get('name'),email:values.get('email'),password:values.get('password'),role:values.get('role'),scopes,...writeView()})});state=r.state;editContext=r.editContext||null;ui.accountRequest=(ui.accountRequest||0)+1;ui.accounts=r.users;ui.accountsError='';form.reset();closeModal();render();toast('User created. They can now sign in with their email and password.');}finally{busy=false;submit.disabled=false;}}
function field(name,label,value='',type='text',opt={}){const req=opt.required?' required':'';let input;if(type==='select')input=`<select name="${name}" ${opt.attrs||''}${req}>${(opt.options||[]).map(o=>{const v=typeof o==='object'?o.value:o,l=typeof o==='object'?o.label:o;return `<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(l)}</option>`;}).join('')}</select>`;else if(type==='textarea')input=`<textarea name="${name}" ${opt.attrs||''}${req}>${esc(value)}</textarea>`;else input=`<input name="${name}" type="${type}" ${type==='file'?'':`value="${esc(value)}"`} ${opt.attrs||''}${req}>`;return `<div class="field ${opt.full?'full':''}"><label>${label}${opt.required?' <span style="color:#b57153">*</span>':''}${input}</label>${opt.hint?`<small>${esc(opt.hint)}</small>`:''}</div>`;}
