function vendorBases(vendorId){return state.bases.filter(b=>b.vendorId===vendorId&&b.lifecycleStatus!=='INACTIVE');}
function itemForBrand(baseId,prefix){return state.items.find(i=>i.baseId===baseId&&i.brandPrefix===prefix&&i.active!==false);}
function basePlanFromLines(lines=[]){const plans=[];for(const l of lines){let p=plans.find(x=>x.baseId===l.baseId);if(!p){p={baseId:l.baseId,unitPrice:major(l.unitPriceMinor),priceAuto:!!l.priceListSnapshot&&!l.priceOverride,specId:l.specId||'',quantities:{GJ:0,KD:0,TT:0}};plans.push(p);}const i=state.items.find(i=>i.id===l.itemId);const prefix=i?.brandPrefix||String(l.code||'').split('-')[0];if(['GJ','KD','TT'].includes(prefix))p.quantities[prefix]=(p.quantities[prefix]||0)+Number(l.quantity||0);}return plans;}
function expandedDraftLines(p){const lines=[];for(const bp of p.basePlans||[]){for(const prefix of ['GJ','KD','TT']){const qty=Number(bp.quantities?.[prefix]||0);if(qty<=0)continue;const item=itemForBrand(bp.baseId,prefix);if(!item)continue;lines.push({itemId:item.id,quantity:qty,unitPrice:bp.unitPrice||'0.00',specId:bp.specId||'',artworkNotes:item.artworkNotes||''});}}return lines;}
function basePriceHint(p,bp,idx=''){const b=state.bases.find(x=>x.id===bp.baseId),attr=idx===''?'':` data-price-hint="${idx}"`;if(!b)return `<span${attr} class="sub">Select a Base Item Code to retrieve the current supplier price.</span>`;const ref=currentApprovedPrice(state,p.vendorId,b.id,p.priceListCurrency||p.currency);if(!ref)return `<span${attr} class="sub">No current ${esc(p.priceListCurrency||p.currency)} price list. Enter the unit price in ${esc(currencyName(p.currency))}.</span>`;const converted=convertedBasePrice(p,b.id);if(converted===null)return `<span${attr} class="sub price-warning">Enter the manual exchange rate and date to convert ${formatMoney(ref.unitPriceMinor,ref.currency)} to ${esc(currencyName(p.currency))}.</span>`;const same=Math.abs(Number(bp.unitPrice||0)-Number(major(converted)))<0.00001;return `<span${attr} class="sub ${same?'':'price-warning'}">${same?'Current base-product price matched':'Warning: entered price differs from current base-product price list'} · ${formatMoney(ref.unitPriceMinor,ref.currency)}${ref.currency!==p.currency?' → '+formatMoney(converted,p.currency):''} · effective ${dt(ref.effectiveDate)} · Rev ${ref.revision||1}</span>`;}
function currencyName(c){return c==='CNY'?'RMB':c;}
function draftConversion(p){try{return priceListConversion(p.priceListCurrency||p.currency,p.currency,p.priceListFxRate,p.priceListFxDate,p.priceListFxQuote??p.priceConversion?.quote??(p.priceConversion?'DIRECT':priceListQuote(p.priceListCurrency||p.currency,p.currency)));}catch{return null;}}
