function priceConversionFields(p,draft=false){const from=p.priceListCurrency||p.currency,to=p.currency;if(from===to)return '';const quote=p.priceListFxQuote??p.priceConversion?.quote??(p.priceConversion?'DIRECT':priceListQuote(from,to)),pair=quote==='USD_CNY';return '<input type="hidden" name="priceListFxQuote" value="'+quote+'">'+field('priceListFxRate',pair?'USD to RMB':currencyName(from)+' to '+currencyName(to),p.priceListFxRate??(p.priceConversion?String(p.priceConversion.rate/1e6):''),'number',{required:true,attrs:'min="0.000001" step="0.000001"'+(draft?' data-draft="priceListFxRate"':''),hint:pair?'1 USD = this many RMB. Enter the current rate.':currencyName(to)+' per 1 '+currencyName(from)+'. Enter the current rate.'})+field('priceListFxDate','Exchange rate date',p.priceListFxDate??p.priceConversion?.date??isoDay(),'date',{required:true,attrs:draft?'data-draft="priceListFxDate"':''});}
