const poCellField=(...args)=>poCellLabel(field(...args)),poCellMoney=(...args)=>poCellLabel(moneyField(...args));
function poRowAmount(bp){try{if((ui.draft.priceListCurrency||ui.draft.currency)!==ui.draft.currency&&!draftConversion(ui.draft))return null;const quantities=['GJ','KD','TT'].filter(k=>itemForBrand(bp.baseId,k)).map(k=>Number(bp.quantities?.[k]||0));if(quantities.some(q=>!Number.isSafeInteger(q)||q<0))return null;const total=quantities.reduce((n,q)=>n+q,0)*toMinor(bp.unitPrice||'0');return Number.isSafeInteger(total)?total:null;}catch{return null;}}
function refreshPoTotals(){if(!ui.draft||!document.querySelector('.po-item-sheet'))return;let total=0,valid=true,qty=0;for(const [i,bp]of ui.draft.basePlans.entries()){const amount=poRowAmount(bp);if(amount===null)valid=false;else total+=amount;for(const k of ['GJ','KD','TT'])if(itemForBrand(bp.baseId,k))qty+=Number(bp.quantities?.[k]||0);const cell=document.querySelector('[data-po-amount="'+i+'"]');if(cell)cell.textContent=amount===null?'—':formatMoney(amount,ui.draft.currency);}const totalCell=document.querySelector('[data-po-total]'),qtyCell=document.querySelector('[data-po-quantity]');if(totalCell)totalCell.textContent=valid&&Number.isSafeInteger(total)?formatMoney(total,ui.draft.currency):'Check entries';if(qtyCell)qtyCell.textContent=Number.isSafeInteger(qty)?qty+' units':'Check quantities';}
