function poItemWorksheet(p){const bases=vendorBases(p.vendorId),selected=new Set(p.basePlans.map(x=>x.baseId));return '<div class="po-entry-workspace"><aside class="po-catalog" aria-label="Supplier item list"><div class="po-catalog-head"><b>Supplier items</b><span data-po-catalog-count>'+bases.length+' items</span></div><input type="search" id="po-item-search" aria-label="Search supplier items" placeholder="Search item name or code" value="'+esc(ui.poItemSearch||'')+'"><div class="po-catalog-list">'+bases.map(b=>{const chosen=selected.has(b.id),usable=['GJ','KD','TT'].some(k=>itemForBrand(b.id,k)),price=poReferenceMinor(p,b.id);return '<div class="po-catalog-row" data-po-catalog-row data-search="'+esc((b.code+' '+b.productName+' '+(b.category||'')).toLowerCase())+'"><div><b>'+esc(b.productName||b.code)+'</b><span>'+esc(b.code)+' · '+(price===null?'Enter price':formatMoney(price,p.priceListCurrency||p.currency))+'</span></div><button type="button" class="button small" data-action="pick-po-item" data-base="'+esc(b.id)+'" aria-label="'+esc((chosen?'Added ':'Add ')+b.code)+'" '+(chosen||!usable?'disabled':'')+'>'+ (chosen?'Added':usable?'Add':'No SKU')+'</button></div>';}).join('')+'<p class="empty" data-po-catalog-empty hidden>No matching supplier items.</p></div></aside><section class="po-sheet-panel" aria-label="Purchase order item worksheet"><div class="po-sheet-heading"><b>Order items</b><span>Tab across · Enter next cell · ↑ ↓ between rows</span></div><div class="po-sheet-scroll" tabindex="0" aria-label="Scroll item worksheet"><table class="po-item-sheet"><thead><tr><th scope="col">#</th><th scope="col">Item</th>'+['GJ','KD','TT'].map(k=>'<th scope="col" title="'+esc(state.brands.find(b=>b.prefix===k)?.name||k)+'">'+k+' qty</th>').join('')+'<th scope="col">Rate ('+esc(currencyName(p.currency))+')</th><th scope="col" class="right">Amount</th><th scope="col"><span class="po-sr-only">Remove</span></th></tr></thead><tbody>'+p.basePlans.map((bp,i)=>{const b=state.bases.find(x=>x.id===bp.baseId),specs=b?.specifications?.filter(x=>x.status==='APPROVED')||[];return '<tr><td>'+(i+1)+'</td><td class="po-item-cell">'+poCellField('base-'+i,'Item '+(i+1),bp.baseId,'select',{required:true,options:[{value:'',label:'Choose an item'},...bases.filter(x=>x.id===bp.baseId||!selected.has(x.id)).map(x=>({value:x.id,label:x.code+' · '+x.productName}))],attrs:'data-plan="'+i+'" data-key="baseId" data-po-col="item"'})+'<details class="po-item-details"><summary>'+esc(!b?'Item details':specs.length?'Version & price reference':'No approved PLM · price reference')+'</summary>'+field('spec-'+i,'Technical version',bp.specId,'select',{options:specs.length?[{value:'',label:'Select approved version'},...specs.map(x=>({value:x.id,label:'v'+x.version}))]:[{value:'',label:'No approved PLM — proceed with warning'}],attrs:'data-plan="'+i+'" data-key="specId"'})+basePriceHint(p,bp,i)+'</details><span data-po-price-warning="'+i+'" class="po-price-warning"></span></td>'+['GJ','KD','TT'].map(k=>{const item=itemForBrand(bp.baseId,k);return '<td>'+poCellField('qty-'+i+'-'+k,k+' quantity, row '+(i+1),bp.quantities?.[k]||0,'number',{attrs:'min="0" step="1" data-plan="'+i+'" data-brand="'+k+'" data-po-col="'+k+'" title="'+esc(item?.code||'No active item for this brand')+'"'+(!item?' disabled':'')})+'</td>';}).join('')+'<td>'+poCellMoney('baseprice-'+i,'Unit price, row '+(i+1),bp.unitPrice,{required:true,attrs:'data-plan="'+i+'" data-key="unitPrice" data-po-col="price"'})+'</td><td class="right po-amount" data-po-amount="'+i+'">'+(poRowAmount(bp)===null?'—':formatMoney(poRowAmount(bp),p.currency))+'</td><td><button type="button" class="icon-button" data-action="remove-base-plan" data-index="'+i+'" aria-label="Remove item row '+(i+1)+'">'+icon('close',14)+'</button></td></tr>';}).join('')+'</tbody></table></div><div class="po-sheet-footer">'+button('Add row','add-base-plan',{},'small','plus')+'<div><span data-po-quantity></span><b data-po-total></b></div></div></section></div>';}
