  const order=candidates.find(x=>x.id===data.id)||candidates[0];
  const milestone=order?paymentSchedule(state,order).find(x=>x.authorized):null;
  ui.payment={reference:'',date:isoDay(),currency:order?.currency||'USD',amount:'',inrRate:order?.currency==='INR'?'1':'',bankCharges:'0',bocUsdRmbRate:'',remarks:'',allocations:[{orderId:order?.id||'',termKey:milestone?.key||'',amount:'',invoiceRate:'1'}]};
