function syncInvoiceFields(){if(ui.modal!=='document')return;const required=document.querySelector('#dialog-form [name=type]')?.value==='COMMERCIAL_INVOICE';for(const name of ['invoiceNumber','invoiceDate']){const input=document.querySelector('#dialog-form [name='+name+']');if(input){input.required=required;input.closest('.field').hidden=!required;}}}
