function fileDb(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const r=indexedDB.open('fh-purchase-alpha10-clean-files',1);r.onupgradeneeded=()=>r.result.createObjectStore('files');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(new Error('Document storage is unavailable in this browser.'));});return dbPromise;}
async function putFile(id,file){const db=await fileDb();await new Promise((resolve,reject)=>{const t=db.transaction('files','readwrite');t.objectStore('files').put(file,id);t.oncomplete=resolve;t.onerror=()=>reject(new Error('The file could not be retained. Check browser storage.'));});}
async function getFile(id){const m=state.files.find(f=>f.id===id);if(m?.demoContent)return new Blob([m.demoContent],{type:'text/plain'});const db=await fileDb();return new Promise((resolve,reject)=>{const r=db.transaction('files').objectStore('files').get(id);r.onsuccess=()=>r.result?resolve(r.result):reject(new Error('File body is not in this review browser.'));r.onerror=()=>reject(r.error);});}
function validateUpload(file){if(!file?.size)throw new Error('Select a non-empty supporting file.');if(file.size>MAX_UPLOAD_BYTES)throw new Error(file.name+': maximum file size is 50 MB.');if(!UPLOAD_EXTENSIONS.includes(file.name.split('.').at(-1).toLowerCase()))throw new Error(file.name+': unsupported file type.');}
async function uploadMany(files,orderIds=[]){files.forEach(validateUpload);const ids=[],links=[...new Set(orderIds)].sort().join('|'),submit=$('#dialog-form [type=submit]'),label=submit?.innerHTML;try{for(const [i,file] of files.entries()){if(submit)submit.textContent=`Uploading ${i+1} of ${files.length}…`;const cached=uploadedFiles.get(file);let id=cached?.actor===user.id&&cached.links===links&&state.files.some(f=>f.id===cached.id)?cached.id:null;if(!id){id=await upload(file,orderIds);uploadedFiles.set(file,{id,actor:user.id,links});}ids.push(id);}return ids;}finally{if(submit)submit.innerHTML=label;}}
async function upload(file,orderIds=[],scope='LAE_IMPORT'){validateUpload(file);if(sandbox){const id=crypto.randomUUID();await putFile(id,file);const next=structuredClone(state);next.files.push({id,name:file.name,mime:file.type||'application/octet-stream',size:file.size,orderIds:[...new Set(orderIds)],scope,uploadedAt:new Date().toISOString(),uploadedBy:user.name});ensureRecordReferences(next);persist(next);state=next;return id;}const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=32768)binary+=String.fromCharCode(...bytes.subarray(i,i+32768));const digest=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify([file.name,scope,[...new Set(orderIds)].sort(),btoa(binary)]))),requestId='upload-'+Array.from(new Uint8Array(digest)).map(v=>v.toString(16).padStart(2,'0')).join('');const r=await api('/files',{method:'POST',headers:{'Idempotency-Key':requestId},body:JSON.stringify({name:file.name,mime:file.type||'application/octet-stream',base64:btoa(binary),orderIds:[...new Set(orderIds)],scope,expectedRevision:state.revision,editContext})});state=r.state;editContext=r.editContext||null;return r.id;}
function download(blob,name){const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function openFile(id){try{const f=state.files.find(f=>f.id===id);if(!f)throw new Error('Document not found.');let blob;if(sandbox)blob=await getFile(id);else{const r=await fetch('/api/files/'+encodeURIComponent(id),{credentials:'same-origin'});if(!r.ok)throw new Error('You do not have access to this file.');blob=await r.blob();}download(blob,f.name);}catch(e){showRequestError(e);}}
