function parseCSV(s){const rows=[];let row=[],cell='',quoted=false;const delimiter=s.split(/\r?\n/)[0].includes(';')&&!s.split(/\r?\n/)[0].includes(',')?';':',';for(let i=0;i<s.length;i++){const c=s[i];if(c==='"'){if(quoted&&s[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===delimiter&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&s[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw new Error('CSV has an unmatched quotation mark.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows;}
async function readSheetWorkbook(file,requiredNormalizedHeaders=[],maxRows=2000,options={}){if(!file||file.size>MAX_UPLOAD_BYTES)throw new Error('Choose an XLSX/CSV file of at most 50 MB.');let sheets=[];if(/\.csv$/i.test(file.name))sheets=[parseCSV((await file.text()).replace(/^\uFEFF/,''))];else if(/\.xlsx$/i.test(file.name)){
 const zip=await JSZip.loadAsync(await file.arrayBuffer());const entries=Object.values(zip.files);if(entries.length>4000||entries.reduce((n,f)=>n+(f._data?.uncompressedSize||0),0)>40*1024*1024)throw new Error('Workbook expands beyond the permitted size.');const xml=s=>{const x=new DOMParser().parseFromString(s.replace(/^(?:\uFEFF|\u00ef\u00bb\u00bf)/,''),'application/xml');if(x.querySelector('parsererror'))throw new Error('Invalid workbook XML.');return x;};const sst=zip.file('xl/sharedStrings.xml'),strings=sst?[...xml(await sst.async('string')).getElementsByTagNameNS('*','si')].map(si=>[...si.getElementsByTagNameNS('*','t')].map(t=>t.textContent).join('')):[];
 const wbf=zip.file('xl/workbook.xml'),rf=zip.file('xl/_rels/workbook.xml.rels');if(!wbf||!rf)throw new Error('Workbook structure is incomplete.');const wb=xml(await wbf.async('string')),rels=xml(await rf.async('string'));
 for(const sh of [...wb.getElementsByTagNameNS('*','sheet')]){const rid=sh.getAttribute('r:id'),rel=[...rels.getElementsByTagNameNS('*','Relationship')].find(r=>r.getAttribute('Id')===rid);let target=rel?.getAttribute('Target');if(!target)continue;target=target.startsWith('/')?target.slice(1):'xl/'+target.replace(/^\.\//,'');const sf=zip.file(target);if(!sf)continue;const doc=xml(await sf.async('string')),data=doc.getElementsByTagNameNS('*','sheetData')[0];if(!data)continue;if(options.rejectFormulas&&doc.getElementsByTagNameNS('*','f').length)throw new Error('Formulas are not accepted in price uploads. Paste values and upload again.');const sr=[];for(const row of data.getElementsByTagNameNS('*','row')){const vals=[];for(const c of row.getElementsByTagNameNS('*','c')){const ref=c.getAttribute('r')||'A1';let col=0;for(const l of ref.match(/[A-Z]+/)[0])col=col*26+l.charCodeAt(0)-64;const type=c.getAttribute('t');let v=c.getElementsByTagNameNS('*','v')[0]?.textContent||'';if(type==='s')v=strings[Number(v)]||'';if(type==='inlineStr')v=[...c.getElementsByTagNameNS('*','t')].map(t=>t.textContent).join('');vals[col-1]=v;}if(vals.some(x=>String(x||'').trim()))sr.push(vals);}sheets.push(sr);}
 }else throw new Error('This alpha accepts XLSX and CSV. Save legacy XLS as XLSX.');
 const normHead=v=>String(v??'').toUpperCase().replace(/[^A-Z0-9]/g,'');let selected=null,headerIndex=-1;for(const rows of sheets){for(let i=0;i<Math.min(rows.length,30);i++){const hs=(rows[i]||[]).map(normHead);if(requiredNormalizedHeaders.every(h=>hs.includes(normHead(h)))){selected=rows;headerIndex=i;break;}}if(selected)break;}if(!selected)throw new Error('No worksheet contains the expected headings: '+requiredNormalizedHeaders.join(', ')+'.');const rows=selected.slice(headerIndex);if(rows.length<2)throw new Error('The selected sheet must have a header and at least one data row.');if(rows.length>maxRows+1)throw new Error('Maximum '+maxRows.toLocaleString()+' data rows per upload.');const headers=rows.shift().map(h=>String(h||'').trim());if(headers.filter(Boolean).length!==new Set(headers.filter(Boolean)).size)throw new Error('Duplicate column headings are not allowed.');return rows.map(row=>Object.fromEntries(headers.map((h,i)=>[h,row[i]??'']).filter(([h])=>h))).filter(r=>Object.values(r).some(v=>String(v||'').trim()));}
async function readWorkbook(file){return readSheetWorkbook(file,['ITEM CODE'],2000);}

async function backup(){const zip=new JSZip();zip.file('workspace.json',JSON.stringify(state,null,2));let missing=0;for(const f of state.files){try{zip.file('files/'+f.id+'-'+f.name,await getFile(f.id));}catch{missing++;}}zip.file('README.txt',`Farming Hub browser review backup\nSoftware ${APP_VERSION}\nMissing evidence bodies: ${missing}\nNot a backup of live VMS or ERP.\n`);download(await zip.generateAsync({type:'blob'}),'FH_Review_Backup_'+isoDay()+'.zip');toast(missing?`Backup exported; ${missing} evidence body/bodies were unavailable.`:'Review data and evidence exported.');}
function printPO(o){const r=o.revisions[ui.revision??o.revisions.length-1];const snap=r?.snapshot||{number:o.number,vendor:vendor(o),currency:o.currency,priceConversion:o.priceConversion,incoterm:o.incoterm,requestedPortDate:o.requestedPortDate,paymentTerms:o.paymentTerms,lines:o.lines.map(l=>({...l,specification:approvedSpec(state,l.baseId,l.specId)})),totalMinor:orderTotal(o),notes:o.notes,attachments:[]};$('.print-sheet')?.remove();const el=document.createElement('div');el.className='print-sheet';el.innerHTML=`<div class="print-head"><div><img class="print-logo" src="${FARMING_HUB_LOGO}" alt="Farming Hub"><div class="eyebrow">FARMING HUB PRIVATE LIMITED</div><h1>Purchase Order</h1><p class="subtitle">LAE Import · ${r?'Issued snapshot':'DRAFT — NOT ISSUED'}</p></div><div class="right"><h2>${esc(snap.number||'Draft')}</h2><p>Software reference ${esc(softwareReference(state,'orders',o.id))}</p><p>PO Revision ${r?.revision??0}</p><p>${dt(r?.at||o.createdAt)}</p></div></div><div class="kv-grid">${kv('Supplier',esc(snap.vendor?.name)+'<br>'+esc(snap.vendor?.code))}${kv('Currency / trade term',esc(snap.currency)+' · '+esc(snap.incoterm))}${kv('Required port arrival',dt(snap.requestedPortDate))}${kv('Payment terms',esc(snap.paymentTerms.name))}${snap.priceConversion?kv('PO exchange rate',poFxSummary(snap.priceConversion)):''}</div><h2>Order lines</h2><table><thead><tr><th>ERP Item Code</th><th>Version</th><th>Qty</th><th>Unit price</th><th>Total</th></tr></thead><tbody>${snap.lines.map(l=>`<tr><td><b>${esc(l.code)}</b><br>${esc(l.name)}</td><td>${esc(l.specification?.version||'Not released')}</td><td>${l.quantity}</td><td>${formatMoney(l.unitPriceMinor,snap.currency)}</td><td>${formatMoney(l.quantity*l.unitPriceMinor,snap.currency)}</td></tr>`).join('')}</tbody></table><h2 class="right">Total ${formatMoney(snap.totalMinor??orderTotal(o),snap.currency)}</h2><h2>Technical requirements annexure</h2>${snap.lines.map(l=>`<div class="print-line"><h3>${esc(l.code)} · ${esc(l.specification?.version||'Unreleased')}</h3><pre>${esc(l.specification?.description||'No approved specification.')}</pre><p><b>Brand packaging / decal requirements:</b> ${esc(l.artworkNotes||'Not supplied')}</p></div>`).join('')}<h2>Issued document manifest</h2><p>${snap.attachments?.length?snap.attachments.map(d=>esc(d.name)+' · '+esc(d.fileId)).join('<br>'):'No additional files attached at the time of this issued snapshot.'}</p><h2>Commercial remarks</h2><pre>${esc(snap.notes||'—')}</pre><p>Issued by: ${esc(r?.actor||'Pending approval')}</p>${state.demo?'<div class="print-warning">DEMONSTRATION ONLY. This is not a real commercial order. Sample products, specifications and approvals are illustrative.</div>':''}`;document.body.append(el);window.print();}
