async function onChange(event){const el=event.target,d=el.dataset;try{if(ui.modal==='vendor-edit'&&el.name==='kind'){syncVendorTypeFields();return;}if(domesticUI.change(el))return;if(ui.modal==='document'&&el.name==='type')syncInvoiceFields();if(referencePages.change(el))return;if(el.id==='module-select'){if(['order-management','vms'].includes(el.value))navigate(el.value);return;}if(vmsModule.change(el))return;
 if(d.orderSelect){if(user.role!=='ADMIN')return;const ids=d.orderSelect==='page'?filteredOrders().slice((ui.page-1)*12,ui.page*12).map(o=>o.id):[d.orderSelect];const selected=new Set(ui.selectedOrders);for(const id of ids)if(el.checked)selected.add(id);else selected.delete(id);ui.selectedOrders=[...selected];render();return;}
 if(el.id==='order-supplier'||el.id==='order-sort'){if(el.id==='order-supplier')ui.orderSupplier=el.value;else if(orderSortOptions.some(([key])=>key===el.value))ui.orderSort=el.value;ui.page=1;ui.selectedOrders=[];render();document.getElementById(el.id)?.focus();return;}
 if(el.id==='order-visibility'){ui.orderList=el.value;ui.orderSupplier='';ui.selectedOrders=[];ui.search='';ui.status='';ui.page=1;render();return;}
 if(['create-user','change-role'].includes(ui.modal)&&el.name==='role'){const hint=$('#new-user-role-hint');if(hint)hint.textContent=userRoleHelp(el.value);return;}
 if(el.id==='demo-role'&&sandbox){user=state.users.find(u=>u.id===el.value);localStorage.setItem(STORE+'-user',user.id);ui.selectedOrders=[];ui.orderList='active';ui.orderSupplier='';ui.orderSort='default';ui.page=1;closeModal();render();}
 else if(['status-filter','task-status','shipment-status'].includes(el.id)){ui.status=el.value;ui.page=1;ui.selectedOrders=[];render();}
 else if(el.id==='category-filter'){ui.category=el.value;ui.page=1;render();}
 else if(d.priceVendor==='select'){ui.data.vendor=el.value;renderModal();}
 else if(el.id==='revision-select'){ui.revision=Number(el.value);render();}
 else if(d.draft){ui.draft[d.draft]=el.value;if(d.draft==='vendorId'){const v=state.vendors.find(v=>v.id===el.value);ui.poItemSearch='';ui.draft.productionDays=v.productionDays;ui.draft.productionOverrideReason='';ui.draft.currency=v.defaultBillingCurrency||v.currency;ui.draft.priceListCurrency=v.defaultPriceListCurrency||v.currency;ui.draft.priceListFxRate='';ui.draft.priceListFxDate=isoDay();ui.draft.priceListFxQuote=priceListQuote(ui.draft.priceListCurrency,ui.draft.currency);ui.draft.paymentMethod=v.defaultPaymentMethod||'TT';ui.draft.routeId=state.routes.find(r=>r.origin===(v.defaultExportPort||'').toUpperCase()&&!r.via)?.id||state.routes.find(r=>r.origin===(v.defaultExportPort||'').toUpperCase())?.id||state.routes[0]?.id||'';ui.draft.paymentTerms=newOrderPaymentTerms(v);ui.draft.basePlans=[{baseId:'',unitPrice:'0.00',specId:'',quantities:{GJ:0,KD:0,TT:0}}];renderModal();}else if(['priceListCurrency','currency','priceListFxRate','priceListFxDate'].includes(d.draft)){if(['priceListCurrency','currency'].includes(d.draft)){ui.draft.priceListFxRate='';ui.draft.priceListFxDate=isoDay();ui.draft.priceListFxQuote=priceListQuote(ui.draft.priceListCurrency,ui.draft.currency);}refreshConvertedPrices();if(['priceListCurrency','currency'].includes(d.draft))renderModal();}}
 else if(d.plan!==undefined){const bp=ui.draft.basePlans[Number(d.plan)];if(d.brand){bp.quantities=bp.quantities||{GJ:0,KD:0,TT:0};bp.quantities[d.brand]=Number(el.value||0);refreshProductionHint();}else{bp[d.key]=el.value;if(d.key==='unitPrice')bp.priceAuto=false;if(d.key==='baseId'){choosePoBase(bp,el.value);const refDays=productionReferenceForDraft(ui.draft);if(refDays){ui.draft.productionDays=refDays;if(!productionOverrideNeeded(ui.draft))ui.draft.productionOverrideReason='';}renderModal();}}}
 else if(d.template==='terms'){ui.draft.paymentTerms=structuredClone(paymentTermsFor(state,'SUPPLIER',true).find(t=>t.id===el.value));renderModal();}
 else if(el.hasAttribute('data-initial-payment-currency'))updateInitialRateLabels(el.value);
 else if(d.pay){ui.payment[d.pay]=el.value;if(d.pay==='currency'){if(el.value!=='USD'){ui.payment.bocUsdRmbRate='';const boc=$('[name=bocUsdRmbRate]');if(boc)boc.value='';}renderModal();}}
 else if(d.payline!==undefined){const a=ui.payment.allocations[Number(d.payline)];a[d.key]=el.value;if(d.key==='orderId'){a.termKey='';renderModal();}}
 else if(d.userScope){const u=state.users.find(u=>u.id===d.userScope),scopes=el.checked?[...u.scopes,d.scope]:u.scopes.filter(s=>s!==d.scope);await command('SAVE_SCOPES',{userId:u.id,scopes},{message:'Division / purchase-type access updated.'});}
 else if(el.id==='master-import-file')await selectImportFile('master',el.files[0],ui.modal==='vendor-import'?['code']:['vendorCode'],500);
 else if(el.id==='item-import-file')await selectImportFile('import',el.files[0],['ITEM CODE'],2000);
 else if(el.id==='tracking-import-file')await selectImportFile('tracking',el.files[0],['REF','STATUS'],1000);
 else if(el.id==='rate-import-file')await selectImportFile('rate',el.files[0],['PORT OF LOADING','O/F USD'],500);
 }catch(e){showRequestError(e);}}
async function selectImportFile(kind,file,headers,limit){
 const token={},modal=ui.modal,values=Object.fromEntries(new FormData($('#dialog-form')));
 ui.importReadToken=token;ui[kind+'Rows']=null;ui[kind+'File']=null;
 const redraw=()=>{renderModal();for(const [name,value] of Object.entries(values)){const el=$('#dialog-form').elements.namedItem(name);if(el&&el.type!=='file')el.value=value;}};
 redraw();if(!file)return;
 try{const rows=await readSheetWorkbook(file,headers,limit);if(ui.importReadToken!==token||ui.modal!==modal)return;
  const preview=kind==='master'?previewMasterImport(state,rows,modal.split('-')[0],user):kind==='tracking'?previewTrackingImport(state,rows):kind==='rate'?previewRateImport(state,rows,'PREVIEW'):previewImport(state,rows);
  if(!preview.length)throw new Error('The file contains no usable rows.');
  ui[kind+'Rows']=rows;ui[kind+'File']=file;redraw();
 }catch(e){if(ui.importReadToken===token&&ui.modal===modal)showError(e.message);}
}
function onInput(event){if(domesticUI.change(event.target))return;if(event.target.matches('[data-arrival-input]')){arrivalCostingUI.preview();return;}if(referencePages.input(event.target))return;if(event.target.id==='vms-search'){vmsModule.change(event.target);return;}if(event.target.id==='po-item-search'){ui.poItemSearch=event.target.value;filterPoCatalog();return;}const el=event.target,d=el.dataset;if(el.id==='view-search'){const p=el.selectionStart;ui.search=el.value;ui.page=1;ui.selectedOrders=[];render();const e=$('#view-search');e?.focus();e?.setSelectionRange(p,p);}else if(d.draft){ui.draft[d.draft]=el.value;if(['priceListFxRate','priceListFxDate'].includes(d.draft))refreshConvertedPrices();if(d.draft==='productionDays'){if(!productionOverrideNeeded(ui.draft))ui.draft.productionOverrideReason='';renderModal();}}else if(d.plan!==undefined){const idx=Number(d.plan),bp=ui.draft.basePlans[idx];if(d.brand){bp.quantities=bp.quantities||{GJ:0,KD:0,TT:0};bp.quantities[d.brand]=Number(el.value||0);refreshProductionHint();}else{bp[d.key]=el.value;if(d.key==='unitPrice'){bp.priceAuto=false;const h=document.querySelector(`[data-price-hint="${idx}"]`),tmp=document.createElement('div');if(h){tmp.innerHTML=basePriceHint(ui.draft,bp,idx);h.replaceWith(tmp.firstElementChild);}}}}else if(d.term!==undefined)ui.draft.paymentTerms.steps[Number(d.term)][d.key]=el.value;else if(d.pay)ui.payment[d.pay]=el.value;else if(d.payline!==undefined)ui.payment.allocations[Number(d.payline)][d.key]=el.value;refreshPoTotals();refreshPoWarnings();}
function loginView(error=''){syncPersonalAppearance(null);$('#app').innerHTML=`<div class="login-page"><section class="login-brand"><div class="brand login-logo-block" style="padding:0 0 45px"><div class="login-logo-shell"><img class="login-brand-logo" src="${FARMING_HUB_LOGO}" alt="Farming Hub"></div></div><div class="eyebrow" style="color:#94b59b">Purchase management</div><h1>From supplier commitment<br>to port arrival.</h1><p>One place for orders, approved specifications, follow-ups and payment history. LAE Import comes first.</p></section><section class="login-form"><form class="login-card" id="login-form"><h2>Welcome to your workspace</h2><p>Sign in with a local pilot account. Existing live VMS accounts are not connected to this build.</p>${error?`<div class="form-error visible">${esc(error)}</div>`:''}${field('email','Email','','email',{required:true})}${field('password','Password','','password',{required:true,attrs:'autocomplete="current-password"'})}<button class="button primary" type="submit">Sign in ${icon('arrow',15)}</button><p style="font-size:10px;margin-top:24px">Setup instructions are in the source package. No shared production password is provided.</p></form></section></div>`;}

async function refreshVms(){const actor=user?.id,r=await api('/bootstrap');if(user?.id!==actor||r.user.id!==actor)throw new Error('Sign in again before syncing.');state=r.state;editContext=r.editContext||null;user=r.user;csrf=r.csrf;return r;}
async function syncVmsEdit(item,owner){
 if(busy)throw new Error('Waiting for the current save to finish.');busy=true;try{
 for(let attempt=0;attempt<3;attempt++){await refreshVms();if(user?.id!==owner)throw new Error('The signed-in account changed.');try{const r=await api('/commands',{method:'POST',body:JSON.stringify({type:'VMS_SYNC_EDIT',payload:{requestId:item.id,vendorId:item.vendorId,commandType:item.commandType,payload:item.payload,base:item.base},expectedRevision:state.revision,editContext})});if(user?.id===owner){state=r.state;editContext=r.editContext||null;user=state.users.find(u=>u.id===owner);}return r.result;}catch(e){if(e.status===409&&/revision|workspace/i.test(e.message)&&attempt<2)continue;throw e;}}
 }finally{busy=false;}
}
